 12→/**
 13→ * Test Vector 1: Standard 129-byte ECIES key with JSON metadata.
 14→ *
 15→ * Key (129 bytes): 0xAA followed by 128 bytes incrementing 0x00..0x7F (128 values).
 16→ * Metadata: UTF-8 encoded '{"iv":"abc","data":"def"}'
 17→ *
 18→ * Expected binary layout:
 19→ *   [0]     = 0x02 (version)
 20→ *   [1..2]  = 0x00 0x81 (key_len = 129, big-endian)
 21→ *   [3..131] = key bytes (129 bytes)
 22→ *   [132..] = metadata bytes
 23→ */
 24→
 25→// Build the 129-byte test key: 0xAA then 0x00..0x7F (128 bytes)
 26→const TEST_KEY_129 = new Uint8Array(129);
 27→TEST_KEY_129[0] = 0xaa;
 28→for (let i = 0; i < 128; i++) {
 29→  TEST_KEY_129[1 + i] = i;
 30→}
 31→
 32→const TEST_METADATA = new TextEncoder().encode('{"iv":"abc","data":"def"}');
 33→
 34→// Pre-computed expected hex for the full blob
 35→// version(02) + keylen(0081) + key(aa 00..7f) + metadata(UTF-8 of JSON)
 36→const EXPECTED_HEX =
 37→  '02' + // version byte
 38→  '0081' + // key_len = 129
 39→  'aa' + // key[0]
 40→  '000102030405060708090a0b0c0d0e0f' + // key[1..16]
 41→  '101112131415161718191a1b1c1d1e1f' + // key[17..32]
 42→  '202122232425262728292a2b2c2d2e2f' + // key[33..48]
 43→  '303132333435363738393a3b3c3d3e3f' + // key[49..64]
 44→  '404142434445464748494a4b4c4d4e4f' + // key[65..80]
 45→  '505152535455565758595a5b5c5d5e5f' + // key[81..96]
 46→  '606162636465666768696a6b6c6d6e6f' + // key[97..112]
 47→  '707172737475767778797a7b7c7d7e7f' + // key[113..128]
 48→  '7b226976223a22616263222c2264617461223a22646566227d'; // metadata JSON
 49→
 50→function toHex(bytes: Uint8Array): string {
 51→  return Array.from(bytes)
 52→    .map((b) => b.toString(16).padStart(2, '0'))
 53→    .join('');
 54→}
 55→
 56→function fromHex(hex: string): Uint8Array {
 57→  const bytes = new Uint8Array(hex.length / 2);
 58→  for (let i = 0; i < bytes.length; i++) {
 59→    bytes[i] = parseInt(hex.substring(i * 2, i * 2 + 2), 16);
 60→  }
 61→  return bytes;
 62→}
 63→
 64→describe('Vault Blob v2 Test Vectors', () => {
 65→  it('Vector 1: serialize produces exact expected hex output', () => {
 66→    const blob = serializeVaultBlobV2(TEST_KEY_129, TEST_METADATA);
