 82→    const parsed = deserializeVaultBlobV2(blob1);
 83→    const blob2 = serializeVaultBlobV2(parsed.encryptedRootFolderKey, parsed.encryptedMetadataJson);
 84→
 85→    expect(toHex(blob2)).toBe(toHex(blob1));
 86→  });
 87→
 88→  it('Vector 1: version byte is BLOB_V2_VERSION', () => {
 89→    const blob = fromHex(EXPECTED_HEX);
