 91→  });
 92→
 93→  it('Vector 2: minimal blob with 1-byte key and 1-byte metadata', () => {
 94→    // Minimal possible blob: version + keylen(0001) + 1 key byte + 1 metadata byte
 95→    const minimalKey = new Uint8Array([0xff]);
 96→    const minimalMeta = new Uint8Array([0x42]);
 97→
 98→    const blob = serializeVaultBlobV2(minimalKey, minimalMeta);
 99→    const expectedMinimalHex = '02' + '0001' + 'ff' + '42';
100→
101→    expect(toHex(blob)).toBe(expectedMinimalHex);
102→
103→    const parsed = deserializeVaultBlobV2(blob);
