 1→//! ECIES key wrapping using secp256k1.
 2→//!
 3→//! Uses the `ecies` Rust crate which is cross-compatible with the `eciesjs` npm package
 4→//! (same author: ecies/rs and ecies/js). Format: ephemeral_pubkey(65) || nonce(16) || tag(16) || ciphertext.
 5→
 6→use thiserror::Error;
 7→
 8→/// secp256k1 uncompressed public key size in bytes (04 prefix + x + y coordinates).
 9→pub const SECP256K1_PUBLIC_KEY_SIZE: usize = 65;
10→
11→/// secp256k1 private key size in bytes.
12→pub const SECP256K1_PRIVATE_KEY_SIZE: usize = 32;
13→
14→/// ECIES minimum ciphertext size: ephemeral pubkey (65) + auth tag (16).
15→pub const ECIES_MIN_CIPHERTEXT_SIZE: usize = SECP256K1_PUBLIC_KEY_SIZE + 16;
16→
17→#[derive(Debug, Error)]
18→pub enum EciesError {
19→    #[error("Key wrapping failed")]
20→    WrappingFailed,
21→    #[error("Key unwrapping failed")]
22→    UnwrappingFailed,
23→    #[error("Invalid public key size")]
24→    InvalidPublicKeySize,
25→    #[error("Invalid public key format")]
26→    InvalidPublicKeyFormat,
27→    #[error("Invalid private key size")]
28→    InvalidPrivateKeySize,
29→}
30→
31→/// Wrap (encrypt) data using ECIES with secp256k1.
32→///
33→/// The `ecies` Rust crate and `eciesjs` npm package produce compatible output.
34→pub fn wrap_key(data: &[u8], recipient_public_key: &[u8]) -> Result<Vec<u8>, EciesError> {
35→    // Validate public key size (uncompressed secp256k1)
36→    if recipient_public_key.len() != SECP256K1_PUBLIC_KEY_SIZE {
37→        return Err(EciesError::InvalidPublicKeySize);
38→    }
39→
40→    // Validate uncompressed public key prefix (0x04)
41→    if recipient_public_key[0] != 0x04 {
42→        return Err(EciesError::InvalidPublicKeyFormat);
43→    }
44→
45→    ecies::encrypt(recipient_public_key, data).map_err(|_| EciesError::WrappingFailed)
46→}
47→
48→/// Unwrap (decrypt) data using ECIES with secp256k1.
49→pub fn unwrap_key(wrapped: &[u8], private_key: &[u8]) -> Result<Vec<u8>, EciesError> {
50→    // Validate private key size
51→    if private_key.len() != SECP256K1_PRIVATE_KEY_SIZE {
52→        return Err(EciesError::InvalidPrivateKeySize);
53→    }
54→
55→    // Validate minimum ciphertext size
56→    if wrapped.len() < ECIES_MIN_CIPHERTEXT_SIZE {
57→        return Err(EciesError::UnwrappingFailed);
58→    }
59→
60→    ecies::decrypt(private_key, wrapped).map_err(|_| EciesError::UnwrappingFailed)
61→}
62→

  1→//! Vault initialization and decryption commands.
  2→
  3→use crate::api::types;
  4→use crate::crypto;
  5→use crate::state::AppState;
  6→
  7→/// Initialize a new vault for a first-time user.
  8→///
  9→/// Generates a root folder AES-256 key and derives a deterministic Ed25519 IPNS
 10→/// keypair via HKDF from the user's private key. ECIES-wraps them with the
 11→/// user's secp256k1 public key, and POSTs everything to `/vault/init`.
 12→pub(crate) async fn initialize_vault(state: &AppState, public_key: &[u8]) -> Result<(), String> {
 13→    // Generate root folder AES-256 key (32 random bytes)
 14→    let root_folder_key = crypto::utils::generate_random_bytes(32);
 15→
 16→    // Derive IPNS keypair deterministically via HKDF from user's private key
 17→    let private_key = state
 18→        .private_key
 19→        .read()
 20→        .await
 21→        .as_ref()
 22→        .ok_or("Private key not available for vault IPNS derivation")?
 23→        .clone();
 24→    let private_key_arr: [u8; 32] = private_key
 25→        .as_slice()
 26→        .try_into()
 27→        .map_err(|_| "Invalid private key length")?;
 28→    let (ipns_private_key, _ipns_public_key, root_ipns_name) =
 29→        crypto::hkdf::derive_vault_ipns_keypair(&private_key_arr)
 30→            .map_err(|e| format!("Vault IPNS derivation failed: {:?}", e))?;
 31→
 32→    // ECIES-wrap keys with user's uncompressed secp256k1 public key
 33→    let encrypted_root_folder_key = crypto::ecies::wrap_key(&root_folder_key, public_key)
 34→        .map_err(|e| format!("Failed to wrap root folder key: {}", e))?;
 35→    let encrypted_ipns_private_key = crypto::ecies::wrap_key(&ipns_private_key, public_key)
 36→        .map_err(|e| format!("Failed to wrap IPNS private key: {}", e))?;
 37→
 38→    // 1. Register vault with backend
 39→    let init_req = types::InitVaultRequest {
 40→        owner_public_key: hex::encode(public_key),
 41→        encrypted_root_folder_key: hex::encode(&encrypted_root_folder_key),
 42→        encrypted_root_ipns_private_key: hex::encode(&encrypted_ipns_private_key),
 43→        root_ipns_name: root_ipns_name.clone(),
 44→    };
 45→
 46→    let resp = state
 47→        .api
 48→        .authenticated_post("/vault/init", &init_req)
 49→        .await
 50→        .map_err(|e| format!("Vault init request failed: {}", e))?;
 51→
 52→    if !resp.status().is_success() {
 53→        let status = resp.status();
 54→        let body = resp.text().await.unwrap_or_default();
 55→        return Err(format!("Vault init failed ({}): {}", status, body));
 56→    }
 57→
 58→    // 2. Create and publish initial empty folder metadata
 59→    //    Without this, FUSE init() can't resolve the root IPNS name.
 60→    log::info!("Publishing initial empty root folder metadata");
 61→
 62→    let empty_metadata = crypto::folder::FolderMetadata {
 63→        version: "v2".to_string(),
 64→        children: vec![],
 65→    };
 66→
 67→    // Encrypt metadata with root folder key
 68→    let folder_key_arr: [u8; 32] = root_folder_key
 69→        .try_into()
 70→        .map_err(|_| "Invalid root folder key length".to_string())?;
 71→    let sealed = crypto::folder::encrypt_folder_metadata(&empty_metadata, &folder_key_arr)
 72→        .map_err(|e| format!("Metadata encryption failed: {}", e))?;
 73→
 74→    // Format as JSON { "iv": "<hex>", "data": "<base64>" }
 75→    let iv_hex = hex::encode(&sealed[..12]);
 76→    use base64::Engine;
 77→    let data_base64 = base64::engine::general_purpose::STANDARD.encode(&sealed[12..]);
 78→    let json_metadata = serde_json::json!({
 79→        "iv": iv_hex,
 80→        "data": data_base64,
 81→    });
 82→    let json_bytes = serde_json::to_vec(&json_metadata)
 83→        .map_err(|e| format!("JSON serialization failed: {}", e))?;
 84→
 85→    // Upload encrypted metadata to IPFS
 86→    let initial_cid = crate::api::ipfs::upload_content(&state.api, &json_bytes).await?;
 87→
 88→    // Create and sign IPNS record (sequence 0, 24h lifetime)
 89→    let ipns_key_arr: [u8; 32] = ipns_private_key.as_slice()
 90→        .try_into()
 91→        .map_err(|_| "Invalid IPNS private key length".to_string())?;
 92→    let value = format!("/ipfs/{}", initial_cid);
 93→    let record = crypto::ipns::create_ipns_record(&ipns_key_arr, &value, 0, 86_400_000)
 94→        .map_err(|e| format!("IPNS record creation failed: {}", e))?;
 95→    let marshaled = crypto::ipns::marshal_ipns_record(&record)
 96→        .map_err(|e| format!("IPNS record marshaling failed: {}", e))?;
 97→    let record_base64 = base64::engine::general_purpose::STANDARD.encode(&marshaled);
 98→
 99→    // Publish IPNS record via backend (sequence 0 - first ever publish, no conflict check needed)
100→    let publish_req = crate::api::ipns::IpnsPublishRequest {
101→        ipns_name: root_ipns_name.clone(),
102→        record: record_base64,
103→        metadata_cid: initial_cid,
104→        encrypted_ipns_private_key: None,
105→        key_epoch: None,
106→        expected_sequence_number: None,
107→    };
108→    match crate::api::ipns::publish_ipns(&state.api, &publish_req).await? {
109→        crate::api::ipns::PublishResult::Success => {}
110→        crate::api::ipns::PublishResult::Conflict { .. } => {
111→            // Sequence 0 should never conflict on vault init -- log and continue
112→            log::warn!("Unexpected conflict on vault init publish (sequence 0)");
113→        }
114→    }
115→
116→    log::info!("Vault initialized and root metadata published for new user");
117→    Ok(())
118→}
119→
120→/// Fetch vault keys from backend and decrypt them using the user's private key.
121→///
122→/// Decrypts:
123→/// - Root folder AES-256 key (32 bytes) from ECIES-wrapped hex
124→/// - Root IPNS Ed25519 private key (32 bytes) from ECIES-wrapped hex
125→///
126→/// The IPNS public key is derivable from the private key if ever needed.
127→/// Stores all keys in AppState (memory only).
128→pub(crate) async fn fetch_and_decrypt_vault(state: &AppState) -> Result<(), String> {
129→    log::info!("Fetching and decrypting vault keys");
130→
131→    // GET /vault
132→    let resp = state
133→        .api
134→        .authenticated_get("/vault")
135→        .await
136→        .map_err(|e| format!("Vault fetch failed: {}", e))?;
137→
138→    if !resp.status().is_success() {
139→        let status = resp.status();
140→        let body = resp.text().await.unwrap_or_default();
141→        return Err(format!("Vault fetch failed ({}): {}", status, body));
142→    }
143→
144→    let vault: types::VaultResponse = resp
145→        .json()
146→        .await
147→        .map_err(|e| format!("Failed to parse vault response: {}", e))?;
148→
149→    // Get private key for decryption
150→    let private_key = state
151→        .private_key
152→        .read()
153→        .await
154→        .as_ref()
155→        .ok_or("Private key not available for vault decryption")?
156→        .clone();
157→
158→    // Decrypt root folder key
159→    let encrypted_root_folder_key = hex::decode(&vault.encrypted_root_folder_key)
160→        .map_err(|_| "Invalid encryptedRootFolderKey hex")?;
161→    let root_folder_key = crypto::ecies::unwrap_key(&encrypted_root_folder_key, &private_key)
162→        .map_err(|e| format!("Failed to decrypt root folder key: {}", e))?;
163→    *state.root_folder_key.write().await = Some(root_folder_key);
164→
165→    // Decrypt root IPNS private key
166→    let encrypted_root_ipns_private_key = hex::decode(&vault.encrypted_root_ipns_private_key)
167→        .map_err(|_| "Invalid encryptedRootIpnsPrivateKey hex")?;
168→    let root_ipns_private_key =
169→        crypto::ecies::unwrap_key(&encrypted_root_ipns_private_key, &private_key)
170→            .map_err(|e| format!("Failed to decrypt root IPNS private key: {}", e))?;
171→
172→    // Verify stored IPNS key matches HKDF derivation (consistency check)
173→    let private_key_arr: [u8; 32] = private_key
174→        .as_slice()
175→        .try_into()
176→        .map_err(|_| "Invalid private key length for HKDF check")?;
177→    if let Ok((expected_ipns_key, _, _)) = crypto::hkdf::derive_vault_ipns_keypair(&private_key_arr) {
178→        if root_ipns_private_key != *expected_ipns_key {
179→            log::warn!("Vault IPNS key mismatch: stored key differs from HKDF derivation");
180→            // Don't block - proceed with stored key for backward compatibility
181→        }
182→    }
183→
184→    *state.root_ipns_private_key.write().await = Some(root_ipns_private_key);
185→
186→    // Store IPNS name and TEE keys
187→    *state.root_ipns_name.write().await = Some(vault.root_ipns_name);
188→    *state.tee_keys.write().await = vault.tee_keys;
189→
190→    log::info!("Vault keys decrypted and stored in memory");
191→    Ok(())
192→}
