192→        let req = IpnsPublishRequest {
193→            ipns_name: "k51test".to_string(),
194→            record: "rec".to_string(),
195→            metadata_cid: "cid".to_string(),
196→            encrypted_ipns_private_key: Some("key".to_string()),
