424→    function hexToBytes(hex) {
425→      const clean = hex.startsWith('0x') ? hex.slice(2) : hex;
426→      if (clean.length % 2 !== 0) throw new Error('Invalid hex: odd length');
427→      const bytes = new Uint8Array(clean.length / 2);
428→      for (let i = 0; i < bytes.length; i++) {
429→        const b = parseInt(clean.substring(i * 2, i * 2 + 2), 16);
430→        if (Number.isNaN(b)) throw new Error('Invalid hex character');
431→        bytes[i] = b;
432→      }
433→      return bytes;
434→    }
435→
436→    function bytesToHex(bytes) {
437→      return Array.from(bytes).map(b => b.toString(16).padStart(2, '0')).join('');
438→    }
