440→    function base64ToBytes(b64) {
441→      const bin = atob(b64);
442→      const bytes = new Uint8Array(bin.length);
443→      for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
444→      return bytes;
445→    }
