452→    // =========================================================================
453→    // Crypto: ECIES Decrypt (matches eciesjs@0.4.16 exactly)
454→    // =========================================================================
455→    async function eciesDecrypt(privKeyBytes, encryptedHex) {
456→      const data = typeof encryptedHex === 'string' ? hexToBytes(encryptedHex) : encryptedHex;
457→
458→      // 1. Extract ephemeral public key (65 bytes, uncompressed, 0x04 prefix)
459→      if (data.length < 65 + 16 + 16) {
460→        throw new Error('ECIES ciphertext too short');
461→      }
462→      const ephemeralPK = data.slice(0, 65);
463→      const payload = data.slice(65);
464→
465→      // 2. Compute ECDH shared point (uncompressed output)
466→      //    eciesjs passes compressed ephemeral PK to getSharedSecret internally
467→      //    but output is uncompressed (compressed=false)
468→      const ephemeralPKCompressed = secp256k1.ProjectivePoint.fromHex(ephemeralPK).toRawBytes(true);
469→      const sharedPoint = secp256k1.getSharedSecret(privKeyBytes, ephemeralPKCompressed, false);
470→
471→      // 3. senderPoint = ephemeral PK uncompressed (65 bytes)
472→      const senderPoint = ephemeralPK;
473→
474→      // 4. Derive shared key: HKDF-SHA256(ikm=senderPoint||sharedPoint, salt=undefined, info=undefined, length=32)
475→      const ikm = concatBytes(senderPoint, sharedPoint);
476→      const sharedKey = hkdf(sha256, ikm, undefined, undefined, 32);
477→
478→      // 5. Extract nonce (16 bytes), tag (16 bytes), ciphertext
479→      const nonce = payload.slice(0, 16);
480→      const tag = payload.slice(16, 32);
481→      const ciphertext = payload.slice(32);
482→
483→      // 6. Decrypt with AES-256-GCM
484→      //    Web Crypto expects ciphertext||tag concatenated
485→      const combined = new Uint8Array(ciphertext.length + tag.length);
486→      combined.set(ciphertext, 0);
487→      combined.set(tag, ciphertext.length);
488→
489→      const cryptoKey = await crypto.subtle.importKey(
490→        'raw', sharedKey, { name: 'AES-GCM' }, false, ['decrypt']
491→      );
492→      const plaintext = await crypto.subtle.decrypt(
493→        { name: 'AES-GCM', iv: nonce }, cryptoKey, combined
494→      );
495→
496→      return new Uint8Array(plaintext);
497→    }
