566→    /**
567→     * Derive a file's IPNS name from user's private key and fileId using HKDF.
568→     * Matches the derivation in @cipherbox/crypto deriveFileIpnsKeypair.
569→     *
570→     * Path: secp256k1 privateKey -> HKDF-SHA256 -> 32-byte Ed25519 seed
571→     *       -> Ed25519 public key -> IPNS name (k51...)
572→     */
573→    async function deriveFileIpnsName(userPrivateKey, fileId) {
574→      const info = new TextEncoder().encode(`cipherbox-file-ipns-v1:${fileId}`);
575→
576→      // 1. HKDF-SHA256 to derive 32-byte Ed25519 seed
577→      const keyMaterial = await crypto.subtle.importKey(
578→        'raw', userPrivateKey, 'HKDF', false, ['deriveBits']
579→      );
580→      const derivedBits = await crypto.subtle.deriveBits(
581→        { name: 'HKDF', hash: 'SHA-256', salt: FILE_HKDF_SALT, info },
582→        keyMaterial, 256
583→      );
584→      const ed25519Seed = new Uint8Array(derivedBits);
585→
586→      // 2. Derive Ed25519 public key from seed
587→      const ed25519PublicKey = await ed.getPublicKeyAsync(ed25519Seed);
588→
589→      // 3. Derive IPNS name from Ed25519 public key
590→      return ed25519PublicKeyToIpnsName(ed25519PublicKey);
591→    }
