593→    /**
594→     * Convert an Ed25519 public key to an IPNS name (k51... base36 CIDv1).
595→     *
596→     * CID structure:
597→     *   0x01 (CIDv1) + 0x72 (libp2p-key codec) + multihash
598→     * Multihash:
599→     *   0x00 (identity hash) + 0x24 (36 bytes digest length) + digest
600→     * Digest (protobuf-encoded Ed25519 public key):
601→     *   0x08 0x01 (field 1: KeyType = Ed25519)
602→     *   0x12 0x20 (field 2: Data, 32 bytes)
603→     *   + 32 bytes public key
604→     */
605→    function ed25519PublicKeyToIpnsName(publicKey) {
606→      // Build CID bytes: version(1) + codec(0x72) + identity-multihash(protobuf key)
607→      const cidBytes = new Uint8Array(40); // 2 + 2 + 4 + 32
608→      cidBytes[0] = 0x01; // CIDv1
609→      cidBytes[1] = 0x72; // libp2p-key multicodec
610→      cidBytes[2] = 0x00; // identity multihash function code
611→      cidBytes[3] = 0x24; // digest length = 36 bytes
612→      // Protobuf: field 1 (KeyType) = Ed25519 = 1
613→      cidBytes[4] = 0x08;
614→      cidBytes[5] = 0x01;
615→      // Protobuf: field 2 (Data) = length-delimited, 32 bytes
616→      cidBytes[6] = 0x12;
617→      cidBytes[7] = 0x20;
618→      // Ed25519 public key bytes
619→      cidBytes.set(publicKey, 8);
620→
621→      // Encode as base36lower with 'k' multibase prefix
622→      return base36Encode(cidBytes);
623→    }
624→
625→    /**
626→     * Base36 encode bytes with 'k' multibase prefix (base36lower).
627→     * Encodes as a big-endian unsigned integer in base36.
628→     */
629→    function base36Encode(bytes) {
630→      const ALPHABET = 'REDACTED';
631→
632→      // Convert bytes to a BigInt (big-endian unsigned)
633→      let n = 0n;
634→      for (const b of bytes) {
635→        n = (n << 8n) | BigInt(b);
636→      }
637→
638→      // Convert to base36
639→      if (n === 0n) return 'k0';
640→      const digits = [];
641→      while (n > 0n) {
642→        digits.push(ALPHABET[Number(n % 36n)]);
643→        n = n / 36n;
644→      }
645→
646→      // Count leading zero bytes for zero-padding
647→      let leadingZeros = 0;
648→      for (const b of bytes) {
649→        if (b === 0) leadingZeros++;
650→        else break;
651→      }
652→      for (let i = 0; i < leadingZeros; i++) {
653→        digits.push('0');
654→      }
655→
656→      digits.reverse();
657→      return 'k' + digits.join('');
658→    }
