681→    // =========================================================================
682→    // IPNS Resolution
683→    // =========================================================================
684→    async function resolveIpns(ipnsName, gatewayUrl) {
685→      const maxRetries = 3;
686→
687→      // Primary: Delegated routing API
688→      for (let attempt = 0; attempt < maxRetries; attempt++) {
689→        try {
690→          const url = `${gatewayUrl}/routing/v1/ipns/${ipnsName}`;
691→          const resp = await fetch(url, {
692→            headers: { 'Accept': 'application/vnd.ipfs.ipns-record' }
693→          });
694→
695→          if (resp.ok) {
696→            // The delegated routing API can return the IPNS record in different formats
697→            // Try JSON first (application/json), then raw record
698→            const contentType = resp.headers.get('Content-Type') || '';

698→            const contentType = resp.headers.get('Content-Type') || '';
699→
700→            if (contentType.includes('application/json')) {
701→              const json = await resp.json();
702→              // Extract CID from the record value
703→              if (json.record && json.record.value) {
704→                return extractCidFromValue(json.record.value);
705→              }
706→              if (json.value) {
707→                return extractCidFromValue(json.value);
708→              }
709→            }
710→
711→            // For vnd.ipfs.ipns-record, the response is a binary IPNS record
712→            // We need to parse the CBOR/protobuf to extract the Value field
713→            const recordBytes = new Uint8Array(await resp.arrayBuffer());
714→            const cid = extractCidFromIpnsRecord(recordBytes);
715→            if (cid) return cid;
716→          }
717→        } catch (e) {
718→          if (attempt < maxRetries - 1) {
719→            await sleep(1000 * Math.pow(2, attempt));
720→            continue;
721→          }
722→        }
723→      }
724→
725→      // Fallback: ipfs.io name resolve API
726→      for (let attempt = 0; attempt < maxRetries; attempt++) {
727→        try {
728→          const url = `https://ipfs.io/api/v0/name/resolve?arg=${ipnsName}`;
729→          const resp = await fetch(url);
730→          if (resp.ok) {
731→            const json = await resp.json();
732→            if (json.Path) {
733→              return extractCidFromValue(json.Path);
734→            }
735→          }
736→        } catch (e) {
737→          if (attempt < maxRetries - 1) {
738→            await sleep(1000 * Math.pow(2, attempt));
739→            continue;
740→          }
741→        }
742→      }
743→
744→      throw new Error(`Failed to resolve IPNS name: ${truncate(ipnsName, 20)}`);
745→    }
746→
747→    function extractCidFromValue(value) {
748→      // Value is typically "/ipfs/bafy..." - extract the CID
749→      if (typeof value === 'string') {
750→        if (value.startsWith('/ipfs/')) return value.slice(6);
751→        return value;
752→      }
753→      // If it's bytes (from CBOR), decode as string
754→      if (value instanceof Uint8Array) {
755→        const str = new TextDecoder().decode(value);
756→        if (str.startsWith('/ipfs/')) return str.slice(6);
757→        return str;
758→      }
759→      throw new Error('Unexpected IPNS value format');
760→    }
761→
762→    function extractCidFromIpnsRecord(recordBytes) {
763→      // IPNS records are protobuf-encoded.
764→      // The Value field is field number 2 (wire type 2 = length-delimited).
765→      // We need to find field 2 in the protobuf.
766→      try {
767→        let offset = 0;
768→        while (offset < recordBytes.length) {
769→          const fieldByte = recordBytes[offset];
770→          const fieldNumber = fieldByte >> 3;
771→          const wireType = fieldByte & 0x07;
772→
773→          offset++;
774→
775→          if (wireType === 2) {
776→            // Length-delimited
777→            let length = 0;
778→            let shift = 0;
779→            while (offset < recordBytes.length) {
780→              const b = recordBytes[offset++];
781→              length |= (b & 0x7f) << shift;
782→              if ((b & 0x80) === 0) break;
783→              shift += 7;
784→            }
785→
786→            if (fieldNumber === 2) {
787→              // Value field - this is the IPFS path
788→              const valueBytes = recordBytes.slice(offset, offset + length);
789→              const value = new TextDecoder().decode(valueBytes);
790→              return extractCidFromValue(value);
791→            }
792→
793→            offset += length;
794→          } else if (wireType === 0) {
795→            // Varint - skip
796→            while (offset < recordBytes.length && (recordBytes[offset] & 0x80) !== 0) offset++;
797→            offset++;
798→          } else {
799→            // Unknown wire type, bail
800→            break;
801→          }
802→        }
803→      } catch (e) {
804→        // Failed to parse protobuf
805→      }
806→      return null;
807→    }
