812→    async function fetchFromIpfs(cid, ipfsGatewayUrl) {
813→      const maxRetries = 3;
814→
815→      for (let attempt = 0; attempt < maxRetries; attempt++) {
816→        try {
817→          const url = `${ipfsGatewayUrl}/ipfs/${cid}`;
818→          const resp = await fetch(url);
819→          if (resp.ok) {
820→            return new Uint8Array(await resp.arrayBuffer());
821→          }
822→          if (resp.status === 404) {
823→            throw new Error(`Content not found on IPFS: ${truncate(cid, 20)}`);
824→          }
