826→          if (e.message.includes('not found')) throw e;
827→          if (attempt < maxRetries - 1) {
828→            await sleep(1000 * Math.pow(2, attempt));
829→            continue;
830→          }
831→          throw new Error(`Failed to fetch from IPFS: ${truncate(cid, 20)}`);
832→        }
833→      }
834→    }
