843→    async function recoverFolder(ipnsName, folderKey, path, gatewayConfig) {
844→      // 1. Resolve IPNS name -> CID
845→      log(`Resolving IPNS: ${truncate(ipnsName, 30)}...`, 'info');
846→      const cid = await resolveIpns(ipnsName, gatewayConfig.ipnsGateway);
847→      log(`  Resolved to CID: ${truncate(cid, 40)}`, 'info');
848→
849→      // 2. Fetch encrypted metadata
850→      log(`Fetching metadata for ${path || '/'}...`, 'info');
851→      const metadataBytes = await fetchFromIpfs(cid, gatewayConfig.ipfsGateway);
852→
853→      // 3. Parse as JSON (encrypted metadata format)
854→      let encryptedMeta;
855→      try {
856→        encryptedMeta = JSON.parse(new TextDecoder().decode(metadataBytes));
857→      } catch (e) {
858→        throw new Error(`Failed to parse metadata JSON for ${path || '/'}`);
859→      }
860→
861→      // 4. Decrypt metadata
862→      log(`Decrypting metadata for ${path || '/'}...`, 'info');
863→      const metadata = await decryptFolderMetadata(encryptedMeta, folderKey);
864→
865→      if (!metadata.children || !Array.isArray(metadata.children)) {
866→        log(`  No children in ${path || '/'}`, 'info');
867→        return;
868→      }
869→
870→      // Reject non-v2 metadata
871→      if (metadata.version !== 'v2') {
872→        log(`  ERROR: Unsupported metadata version "${metadata.version}" for ${path || '/'} (only v2 supported). Skipping folder.`, 'error');
873→        errorCount++;
874→        return;
875→      }
876→
877→      log(`  Found ${metadata.children.length} items in ${path || '/'}`, 'success');
878→
879→      // 5. Process each child
880→      for (const child of metadata.children) {
881→        if (child.type === 'folder') {
882→          try {
883→            // ECIES-decrypt subfolder keys
884→            log(`Decrypting keys for folder: ${child.name}`, 'info');
885→            const subFolderKey = await eciesDecrypt(privateKeyBytes, child.folderKeyEncrypted);
886→
887→            // We decrypt the IPNS private key for completeness but only need the name
888→            // (ipnsPrivateKey is 64-byte libp2p format: seed||pubkey)
889→            const subPath = path ? `${path}/${child.name}` : child.name;
890→
891→            // Recurse into subfolder
892→            await recoverFolder(child.ipnsName, subFolderKey, subPath, gatewayConfig);
893→          } catch (e) {
894→            log(`  ERROR recovering folder "${child.name}": ${e.message}`, 'error');
895→            errorCount++;
896→          }
897→        } else if (child.type === 'file') {
