document.getElementById('btn-load').addEventListener('click', async () => {
  clearError(1);

  if (recoveryMethod === 'ipfs-direct') {
    // ── IPFS-direct recovery path ──
    const keyText = document.getElementById('direct-key-text').value.trim();
    if (!keyText) {
      showError(1, 'Please provide your private key.');
      return;
    }

    try {
      // Parse private key
      if (/^(0x)?[0-9a-fA-F]{64}$/.test(keyText)) {
        privateKeyBytes = hexToBytes(keyText);
      } else {
        try { privateKeyBytes = hexToBytes(keyText); }
        catch { try { privateKeyBytes = base64ToBytes(keyText); }
        catch { showError(1, 'Could not parse private key. Provide 32 bytes as 64 hex characters.'); return; } }
      }

      if (privateKeyBytes.length !== 32) {
        showError(1, `Private key must be 32 bytes (got ${privateKeyBytes.length} bytes).`);
        privateKeyBytes = null;
        return;
      }

      const btn = document.getElementById('btn-load');
      btn.disabled = true;
      btn.textContent = '[ Deriving IPNS name... ]';

      // Derive vault IPNS name from private key
      directRootIpnsName = await deriveVaultIpnsName(privateKeyBytes);

      btn.disabled = false;
      btn.textContent = '[ Continue ]';

      // Show derived info
      let infoHtml = `<div class="field"><span class="field-name">Derived rootIpnsName:</span> <span class="field-value">${truncate(directRootIpnsName, 50)}</span></div>`;
      infoHtml += `<div class="field"><span class="field-name">Recovery mode:</span> <span class="field-value">IPFS-direct (v2 blob)</span></div>`;
      document.getElementById('export-info').innerHTML = infoHtml;

      // Skip Step 2 (key already provided) and go directly to Step 3
      // But first we need to try reading the rootFolderKey from IPFS
      const ipnsGateway = document.getElementById('direct-ipns-gateway').value.trim().replace(/\/+$/, '');
      const ipfsGateway = document.getElementById('direct-ipfs-gateway').value.trim().replace(/\/+$/, '');

      btn.disabled = true;
      btn.textContent = '[ Resolving vault... ]';

      try {
        // 1. Resolve IPNS to CID
        const cid = await resolveIpns(directRootIpnsName, ipnsGateway);

        // 2. Fetch blob from IPFS
        const blobBytes = await fetchFromIpfs(cid, ipfsGateway);

        // 3. Detect version
        if (detectBlobVersion(blobBytes) !== 2) {
          showError(1, 'The vault blob at this IPNS name is v1 format. Use "From Export File" recovery method instead.');
          btn.disabled = false;
          btn.textContent = '[ Continue ]';
          return;
        }

        // 4. Extract and decrypt rootFolderKey from v2 blob header
        const { encryptedRootFolderKey } = deserializeVaultBlobV2(blobBytes);
        rootFolderKey = await eciesDecrypt(privateKeyBytes, encryptedRootFolderKey);

        btn.disabled = false;
        btn.textContent = '[ Continue ]';

        // Pre-populate gateway config and skip to Step 3
        document.getElementById('ipns-gateway').value = ipnsGateway;
        document.getElementById('ipfs-gateway').value = ipfsGateway;

        // Set exportData with rootIpnsName for the recovery flow
        exportData = { rootIpnsName: directRootIpnsName };

        showStep(3);
      } catch (resolveErr) {
        btn.disabled = false;
        btn.textContent = '[ Continue ]';
        showError(1, 'Failed to resolve vault from IPFS: ' + resolveErr.message);
      }
    } catch (e) {
      showError(1, 'Error: ' + e.message);
    }
    return;
  }

  // ── Export file recovery path (original) ──
  let jsonText = '';
  const fileInput = document.getElementById('export-file');
  const textInput = document.getElementById('export-text');

  if (fileInput.files.length > 0) {
    jsonText = await fileInput.files[0].text();
  } else if (textInput.value.trim()) {
    jsonText = textInput.value.trim();
  } else {
    showError(1, 'Please select a file or paste the export JSON.');
    return;
  }

  try {
    const parsed = JSON.parse(jsonText);

    if (parsed.format !== 'cipherbox-vault-export') {
      showError(1, 'Invalid export file: missing or incorrect "format" field. Expected "cipherbox-vault-export".');
      return;
    }

    if (parsed.version !== '1.0') {
      showError(1, `Unsupported export version: "${parsed.version}". This tool supports version "1.0".`);
      return;
    }

    // Handle migrated vaults with null encrypted keys
    if (!parsed.rootIpnsName) {
      showError(1, 'Export file is missing rootIpnsName field.');
      return;
    }

    if (!parsed.encryptedRootFolderKey || !parsed.encryptedRootIpnsPrivateKey) {
      showError(1, 'This export is from a migrated vault (encrypted keys are null). Use "From IPFS (v2 blob)" recovery method instead, which only needs your private key.');
      return;
    }

    exportData = parsed;

    // Show parsed info in step 2
    let infoHtml = `<div class="field"><span class="field-name">rootIpnsName:</span> <span class="field-value">${truncate(parsed.rootIpnsName, 50)}</span></div>`;
    if (parsed.exportedAt) {
      infoHtml += `<div class="field"><span class="field-name">exportedAt:</span> <span class="field-value">${parsed.exportedAt}</span></div>`;
    }
    if (parsed.derivationInfo) {
      infoHtml += `<div class="field"><span class="field-name">derivationInfo:</span> <span class="field-value">${JSON.stringify(parsed.derivationInfo)}</span></div>`;
    }
    document.getElementById('export-info').innerHTML = infoHtml;

    showStep(2);
  } catch (e) {
    showError(1, 'Failed to parse JSON: ' + e.message);
  }
});

