 1→/**
 2→ * @cipherbox/crypto - Vault IPNS Key Derivation
 3→ *
 4→ * Derives a deterministic Ed25519 IPNS keypair for the user's vault
 5→ * from the user's secp256k1 privateKey using HKDF-SHA256.
 6→ *
 7→ * Derivation path:
 8→ *   secp256k1 privateKey (32 bytes)
 9→ *     -> HKDF-SHA256(salt="CipherBox-v1", info="cipherbox-vault-ipns-v1")
10→ *     -> 32-byte Ed25519 seed
11→ *     -> Ed25519 keypair
12→ *     -> IPNS name (k51...)
13→ *
14→ * This enables self-sovereign vault recovery: recovery phrase -> privateKey
15→ * -> derive vault IPNS key -> resolve IPNS -> decrypt vault.
16→ *
17→ * Domain separation: Uses "cipherbox-vault-ipns-v1" info (different from
18→ * registry's "cipherbox-device-registry-ipns-v1"), ensuring the same
19→ * privateKey produces different IPNS keypairs for vault vs registry.
20→ */
21→
22→import { deriveKey } from '../keys/derive';
23→import * as ed from '@noble/ed25519';
24→import { deriveIpnsName } from '../ipns/derive-name';
25→import { CryptoError } from '../types';
26→import { SECP256K1_PRIVATE_KEY_SIZE } from '../constants';
27→
28→const VAULT_HKDF_SALT = new TextEncoder().encode('CipherBox-v1');
29→const VAULT_HKDF_INFO = new TextEncoder().encode('cipherbox-vault-ipns-v1');
30→
31→/**
32→ * Derive the deterministic Ed25519 IPNS keypair for the user's vault.
33→ *
34→ * Given the same secp256k1 privateKey, this always produces the same
35→ * IPNS name, enabling vault discovery from any device with the user's key.
36→ *
37→ * @param userPrivateKey - 32-byte secp256k1 private key
38→ * @returns Ed25519 keypair and IPNS name for the vault
39→ * @throws CryptoError if the private key is not 32 bytes
40→ */
41→export async function deriveVaultIpnsKeypair(userPrivateKey: Uint8Array): Promise<{
42→  privateKey: Uint8Array;
43→  publicKey: Uint8Array;
44→  ipnsName: string;
45→}> {
46→  // Validate input key length
47→  if (userPrivateKey.length !== SECP256K1_PRIVATE_KEY_SIZE) {
48→    throw new CryptoError('Invalid private key size for vault derivation', 'INVALID_KEY_SIZE');
49→  }
50→
51→  // 1. HKDF: secp256k1 privateKey -> 32-byte Ed25519 seed
52→  const ed25519Seed = await deriveKey({
53→    inputKey: userPrivateKey,
54→    salt: VAULT_HKDF_SALT,
55→    info: VAULT_HKDF_INFO,
56→    outputLength: 32,
57→  });
58→
59→  // 2. Derive Ed25519 public key from seed (deterministic)
60→  const ed25519PublicKey = await ed.getPublicKeyAsync(ed25519Seed);
61→
62→  // 3. Derive IPNS name from Ed25519 public key (k51... format)
63→  const ipnsName = await deriveIpnsName(ed25519PublicKey);
64→
65→  return {
66→    privateKey: ed25519Seed,
67→    publicKey: ed25519PublicKey,
68→    ipnsName,
69→  };
70→}
71→

 1→/**
 2→ * @cipherbox/crypto - HKDF Key Derivation
 3→ *
 4→ * HKDF-SHA256 key derivation using Web Crypto API.
 5→ * Used for deriving context-specific keys from master key material.
 6→ */
 7→
 8→import { CryptoError } from '../types';
 9→import { AES_KEY_SIZE } from '../constants';
10→
11→/**
12→ * Parameters for HKDF key derivation.
13→ */
14→export type DeriveKeyParams = {
15→  /** Input key material (e.g., master key, signature) */
16→  inputKey: Uint8Array;
17→  /** Salt for HKDF (domain separation) */
18→  salt: Uint8Array;
19→  /** Info/context for HKDF (additional context) */
20→  info: Uint8Array;
21→  /** Output length in bytes (defaults to 32) */
22→  outputLength?: number;
23→};
24→
25→/**
26→ * Derive a key using HKDF-SHA256.
27→ *
28→ * @param params - Derivation parameters
29→ * @returns Derived key bytes
30→ * @throws CryptoError if derivation fails
31→ *
32→ * @example
33→ * ```typescript
34→ * const derivedKey = await deriveKey({
35→ *   inputKey: masterKey,
36→ *   salt: new TextEncoder().encode('CipherBox-v1'),
37→ *   info: new TextEncoder().encode('folder-key'),
38→ *   outputLength: 32
39→ * });
40→ * ```
41→ */
42→export async function deriveKey(params: DeriveKeyParams): Promise<Uint8Array> {
43→  const { inputKey, salt, info, outputLength = AES_KEY_SIZE } = params;
44→
45→  try {
46→    // Copy Uint8Arrays to ensure we have proper ArrayBuffers (not SharedArrayBuffer)
47→    // This also handles any potential offset issues from TypedArray subviews
48→    const inputKeyBuffer = new Uint8Array(inputKey).buffer as ArrayBuffer;
49→    const saltBuffer = new Uint8Array(salt).buffer as ArrayBuffer;
50→    const infoBuffer = new Uint8Array(info).buffer as ArrayBuffer;
51→
52→    // Import input key as raw key material for HKDF
53→    const keyMaterial = await crypto.subtle.importKey(
54→      'raw',
55→      inputKeyBuffer,
56→      'HKDF',
57→      false, // not extractable
58→      ['deriveBits']
59→    );
60→
61→    // Derive key using HKDF-SHA256
62→    const derivedBits = await crypto.subtle.deriveBits(
63→      {
64→        name: 'HKDF',
65→        hash: 'SHA-256',
66→        salt: saltBuffer,
67→        info: infoBuffer,
68→      },
69→      keyMaterial,
70→      outputLength * 8 // deriveBits takes length in bits
71→    );
72→
73→    return new Uint8Array(derivedBits);
74→  } catch {
75→    // Generic error to prevent information leakage
76→    throw new CryptoError('Key derivation failed', 'ENCRYPTION_FAILED');
77→  }
78→}
