  1→//! Vault blob v2 format: binary envelope for root folder IPFS blobs.
  2→//!
  3→//! Format: 0x02 | uint16_BE(key_len) | ECIES_encrypted_key | AES_GCM_metadata_json
  4→//!
  5→//! v1 blobs are plain JSON: {"iv":"...","data":"..."}
  6→//! v2 blobs prepend the ECIES-wrapped rootFolderKey before the metadata JSON.
  7→
  8→/// Version byte for v2 format.
  9→pub const BLOB_V2_VERSION: u8 = 0x02;
 10→
 11→/// Detect whether a vault blob is v1 (JSON) or v2 (binary envelope).
 12→///
 13→/// v1 blobs start with 0x7B ('{' -- JSON). v2 blobs start with 0x02.
 14→pub fn detect_blob_version(blob: &[u8]) -> u8 {
 15→    if !blob.is_empty() && blob[0] == BLOB_V2_VERSION {
 16→        2
 17→    } else {
 18→        1
 19→    }
 20→}
 21→
 22→/// Serialize a vault blob v2.
 23→///
 24→/// Produces: `0x02 | uint16_BE(key_len) | encrypted_root_folder_key | encrypted_metadata_json`
 25→pub fn serialize_vault_blob_v2(
 26→    encrypted_root_folder_key: &[u8],
 27→    encrypted_metadata_json: &[u8],
 28→) -> Vec<u8> {
 29→    let key_len = encrypted_root_folder_key.len() as u16;
 30→    let mut result =
 31→        Vec::with_capacity(3 + encrypted_root_folder_key.len() + encrypted_metadata_json.len());
 32→    result.push(BLOB_V2_VERSION);
 33→    result.push((key_len >> 8) as u8);
 34→    result.push((key_len & 0xff) as u8);
 35→    result.extend_from_slice(encrypted_root_folder_key);
 36→    result.extend_from_slice(encrypted_metadata_json);
 37→    result
 38→}
 39→
 40→/// Deserialize a vault blob v2 into (encrypted_key, encrypted_metadata_json).
 41→///
 42→/// Returns borrowed slices into the original blob for zero-copy parsing.
 43→pub fn deserialize_vault_blob_v2(blob: &[u8]) -> Result<(&[u8], &[u8]), String> {
 44→    if blob.len() < 3 {
 45→        return Err(format!(
 46→            "Vault blob too short for v2 header (need at least 3 bytes, have {})",
 47→            blob.len()
 48→        ));
 49→    }
 50→    if blob[0] != BLOB_V2_VERSION {
 51→        return Err("Not a v2 vault blob".into());
 52→    }
 53→    let key_len = ((blob[1] as usize) << 8) | (blob[2] as usize);
 54→    if blob.len() < 3 + key_len {
 55→        return Err(format!(
 56→            "Vault blob too short for key (expected {} bytes, have {})",
 57→            key_len,
 58→            blob.len() - 3
 59→        ));
 60→    }
 61→    Ok((&blob[3..3 + key_len], &blob[3 + key_len..]))
 62→}
 63→
 64→#[cfg(test)]
 65→mod tests {
 66→    use super::*;
 67→
 68→    #[test]
 69→    fn test_round_trip() {
 70→        let key = vec![0xAA; 129];
 71→        let metadata = b"{\"iv\":\"abc\",\"data\":\"def\"}";
 72→        let blob = serialize_vault_blob_v2(&key, metadata);
 73→        let (decoded_key, decoded_meta) = deserialize_vault_blob_v2(&blob).unwrap();
 74→        assert_eq!(decoded_key, key.as_slice());
 75→        assert_eq!(decoded_meta, metadata);
 76→    }
 77→
 78→    #[test]
 79→    fn test_detect_v2() {
 80→        let blob = serialize_vault_blob_v2(&[0; 129], b"test");
 81→        assert_eq!(detect_blob_version(&blob), 2);
 82→    }
 83→
 84→    #[test]
 85→    fn test_detect_v1() {
 86→        let v1 = b"{\"iv\":\"abc\",\"data\":\"def\"}";
 87→        assert_eq!(detect_blob_version(v1), 1);
 88→    }
 89→
 90→    #[test]
 91→    fn test_deserialize_v1_blob_errors() {
 92→        let v1 = b"{\"iv\":\"abc\"}";
 93→        assert!(deserialize_vault_blob_v2(v1).is_err());
 94→    }
 95→
 96→    #[test]
 97→    fn test_deserialize_empty_blob_errors() {
 98→        assert!(deserialize_vault_blob_v2(&[]).is_err());
 99→    }
100→
101→    #[test]
102→    fn test_deserialize_short_blob_errors() {
103→        assert!(deserialize_vault_blob_v2(&[0x02, 0x00]).is_err());
104→    }
105→
106→    #[test]
107→    fn test_key_len_overflow_errors() {
108→        // Claim key is 1000 bytes but only provide 5
109→        let blob = vec![0x02, 0x03, 0xE8, 0, 0, 0, 0, 0];
110→        assert!(deserialize_vault_blob_v2(&blob).is_err());
111→    }
112→
113→    #[test]
114→    fn test_header_format() {
115→        let key = vec![0xBB; 129];
116→        let meta = b"meta";
117→        let blob = serialize_vault_blob_v2(&key, meta);
118→        assert_eq!(blob[0], 0x02);
119→        assert_eq!(blob[1], 0x00); // 129 >> 8 = 0
120→        assert_eq!(blob[2], 0x81); // 129 & 0xFF = 0x81
121→        assert_eq!(&blob[3..132], key.as_slice());
122→        assert_eq!(&blob[132..], b"meta");
123→    }
124→
125→    // Cross-platform test vector: MUST match TypeScript vault-blob-vectors.test.ts
126→    // Key (129 bytes): 0xAA followed by 128 bytes incrementing 0x00..0x7F
127→    // Metadata: UTF-8 of '{"iv":"abc","data":"def"}'
128→    // Expected hex: 02 0081 aa 0001...7f 7b226976...7d
129→    #[test]
130→    fn test_cross_platform_vector() {
131→        // Build the same 129-byte key as TypeScript test vector
132→        let mut key = vec![0xAA];
133→        for i in 0u8..128 {
134→            key.push(i);
135→        }
136→        assert_eq!(key.len(), 129);
137→
138→        let metadata = b"{\"iv\":\"abc\",\"data\":\"def\"}";
139→        let blob = serialize_vault_blob_v2(&key, metadata);
140→
141→        // Verify structure
142→        assert_eq!(blob[0], 0x02);
143→        assert_eq!(blob[1], 0x00);
144→        assert_eq!(blob[2], 0x81); // 129
145→        assert_eq!(blob.len(), 3 + 129 + metadata.len());
146→
147→        // Verify exact hex matches TypeScript EXPECTED_HEX
148→        let blob_hex = hex::encode(&blob);
149→        let expected_hex = concat!(
150→            "02",   // version byte
151→            "0081", // key_len = 129
152→            "aa",   // key[0]
153→            "000102030405060708090a0b0c0d0e0f", // key[1..16]
154→            "101112131415161718191a1b1c1d1e1f", // key[17..32]
155→            "202122232425262728292a2b2c2d2e2f", // key[33..48]
156→            "303132333435363738393a3b3c3d3e3f", // key[49..64]
157→            "404142434445464748494a4b4c4d4e4f", // key[65..80]
158→            "505152535455565758595a5b5c5d5e5f", // key[81..96]
159→            "606162636465666768696a6b6c6d6e6f", // key[97..112]
160→            "707172737475767778797a7b7c7d7e7f", // key[113..128]
161→            "7b226976223a22616263222c2264617461223a22646566227d", // metadata JSON
162→        );
163→        assert_eq!(blob_hex, expected_hex);
164→
165→        // Round-trip
166→        let (dk, dm) = deserialize_vault_blob_v2(&blob).unwrap();
167→        assert_eq!(dk, key.as_slice());
168→        assert_eq!(dm, metadata);
169→    }
170→
171→    // Cross-platform test vector 2: minimal blob (1-byte key, 1-byte metadata)
172→    // Must match TypeScript Vector 2
173→    #[test]
174→    fn test_cross_platform_minimal_vector() {
175→        let key = vec![0xFF];
176→        let meta = vec![0x42];
177→        let blob = serialize_vault_blob_v2(&key, &meta);
178→        let expected_hex = "020001ff42";
179→        assert_eq!(hex::encode(&blob), expected_hex);
180→
181→        let (dk, dm) = deserialize_vault_blob_v2(&blob).unwrap();
182→        assert_eq!(dk, &[0xFF]);
183→        assert_eq!(dm, &[0x42]);
184→    }
185→}
