493→    // =========================================================================
494→    // Utility Functions
495→    // =========================================================================
496→    function hexToBytes(hex) {
497→      const clean = hex.startsWith('0x') ? hex.slice(2) : hex;
498→      if (clean.length % 2 !== 0) throw new Error('Invalid hex: odd length');
499→      const bytes = new Uint8Array(clean.length / 2);
500→      for (let i = 0; i < bytes.length; i++) {
501→        const b = parseInt(clean.substring(i * 2, i * 2 + 2), 16);
502→        if (Number.isNaN(b)) throw new Error('Invalid hex character');
503→        bytes[i] = b;
504→      }
505→      return bytes;
506→    }
507→
508→    function bytesToHex(bytes) {
509→      return Array.from(bytes).map(b => b.toString(16).padStart(2, '0')).join('');
510→    }
511→
512→    function base64ToBytes(b64) {
513→      const bin = atob(b64);
514→      const bytes = new Uint8Array(bin.length);
515→      for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
516→      return bytes;
517→    }
518→
519→    function truncate(str, len) {
520→      if (str.length <= len) return str;
521→      return str.slice(0, len) + '...';
522→    }
523→
524→    // =========================================================================
525→    // Vault Blob v2 Parsing
526→    // =========================================================================
527→    const BLOB_V2_VERSION = 0x02;
528→
529→    function detectBlobVersion(blob) {
530→      return (blob.length > 0 && blob[0] === BLOB_V2_VERSION) ? 2 : 1;
531→    }
532→
533→    function deserializeVaultBlobV2(blob) {
534→      if (blob.length < 3) throw new Error('Blob too short for v2 header');
