251→/// Merge local children onto remote children to resolve a concurrent-edit conflict.
252→///
253→/// Strategy (last-writer-wins per child, additive merge):
254→/// - Start with remote children as base
255→/// - For each child also present locally (by IPNS name): use local version (handles rename)
256→/// - For each child present locally but NOT in remote: add it (new file/folder from this device)
257→/// - For each child present in remote but NOT locally: preserve remote (without tombstones we
258→///   cannot distinguish "local deleted it" from "local never saw it", so we err on the side of
259→///   preserving data to avoid dropping concurrent additions)
260→///
261→/// This is a purely additive merge -- no deletions are performed.
262→#[cfg(any(feature = "fuse", feature = "winfsp"))]
263→fn merge_folder_children(
264→    local: &crate::crypto::folder::FolderMetadata,
265→    remote: crate::crypto::folder::FolderMetadata,
266→) -> crate::crypto::folder::FolderMetadata {
267→    use crate::crypto::folder::FolderChild;
268→
269→    /// Extract the stable IPNS identifier for a child entry.
270→    fn child_ipns_key(child: &FolderChild) -> &str {
271→        match child {
272→            FolderChild::Folder(f) => f.ipns_name.as_str(),
273→            FolderChild::File(f) => f.file_meta_ipns_name.as_str(),
274→        }
275→    }
276→
277→    // Build lookup map keyed by IPNS name for local children.
278→    let local_by_ipns: std::collections::HashMap<String, &FolderChild> = local
279→        .children
280→        .iter()
281→        .map(|c| (child_ipns_key(c).to_string(), c))
282→        .collect();
283→
284→    let mut merged: Vec<FolderChild> = Vec::new();
285→    let mut seen_ipns: std::collections::HashSet<String> = std::collections::HashSet::new();
286→
287→    // Walk remote children in original order (deterministic iteration).
288→    // If local has a version of this child, use local (handles rename/modify).
289→    // Otherwise, preserve the remote child -- without tombstones we cannot
290→    // distinguish "local deleted it" from "local never saw it", so we err on
291→    // the side of preserving data to avoid dropping concurrent additions.
292→    for remote_child in &remote.children {
293→        let ipns = child_ipns_key(remote_child).to_string();
294→        if let Some(local_child) = local_by_ipns.get(&ipns) {
295→            merged.push((*local_child).clone());
296→        } else {
297→            // Preserve remote child to avoid dropping concurrent additions.
298→            merged.push(remote_child.clone());
299→        }
300→        seen_ipns.insert(ipns);
301→    }
302→
303→    // Add any locally-added children that don't exist in remote (new files/folders).
304→    for local_child in &local.children {
305→        let ipns = child_ipns_key(local_child).to_string();
306→        if !seen_ipns.contains(&ipns) {
307→            merged.push(local_child.clone());
308→        }
309→    }
310→
311→    crate::crypto::folder::FolderMetadata {
312→        version: "v2".to_string(),
313→        children: merged,
314→    }
315→}
