716→    /**
717→     * Convert an Ed25519 public key to an IPNS name (k51... base36 CIDv1).
718→     *
719→     * CID structure:
720→     *   0x01 (CIDv1) + 0x72 (libp2p-key codec) + multihash
721→     * Multihash:
722→     *   0x00 (identity hash) + 0x24 (36 bytes digest length) + digest
723→     * Digest (protobuf-encoded Ed25519 public key):
724→     *   0x08 0x01 (field 1: KeyType = Ed25519)
725→     *   0x12 0x20 (field 2: Data, 32 bytes)
726→     *   + 32 bytes public key
727→     */
728→    function ed25519PublicKeyToIpnsName(publicKey) {
729→      // Build CID bytes: version(1) + codec(0x72) + identity-multihash(protobuf key)
730→      const cidBytes = new Uint8Array(40); // 2 + 2 + 4 + 32
731→      cidBytes[0] = 0x01; // CIDv1
732→      cidBytes[1] = 0x72; // libp2p-key multicodec
733→      cidBytes[2] = 0x00; // identity multihash function code
734→      cidBytes[3] = 0x24; // digest length = 36 bytes
735→      // Protobuf: field 1 (KeyType) = Ed25519 = 1
736→      cidBytes[4] = 0x08;
737→      cidBytes[5] = 0x01;
738→      // Protobuf: field 2 (Data) = length-delimited, 32 bytes
739→      cidBytes[6] = 0x12;
740→      cidBytes[7] = 0x20;
741→      // Ed25519 public key bytes
742→      cidBytes.set(publicKey, 8);
743→
744→      // Encode as base36lower with 'k' multibase prefix
745→      return base36Encode(cidBytes);
