748→    /**
749→     * Base36 encode bytes with 'k' multibase prefix (base36lower).
750→     * Encodes as a big-endian unsigned integer in base36.
751→     */
752→    function base36Encode(bytes) {
753→      const ALPHABET = 'REDACTED';
754→
755→      // Convert bytes to a BigInt (big-endian unsigned)
756→      let n = 0n;
757→      for (const b of bytes) {
758→        n = (n << 8n) | BigInt(b);
759→      }
760→
761→      // Convert to base36
762→      if (n === 0n) return 'k0';
763→      const digits = [];
764→      while (n > 0n) {
765→        digits.push(ALPHABET[Number(n % 36n)]);
766→        n = n / 36n;
767→      }
768→
769→      // Count leading zero bytes for zero-padding
770→      let leadingZeros = 0;
771→      for (const b of bytes) {
772→        if (b === 0) leadingZeros++;
773→        else break;
774→      }
775→      for (let i = 0; i < leadingZeros; i++) {
776→        digits.push('0');
777→      }
778→
779→      digits.reverse();
780→      return 'k' + digits.join('');
781→    }
