807→    async function resolveIpns(ipnsName, gatewayUrl) {
808→      const maxRetries = 3;
809→
810→      // Primary: Delegated routing API
811→      for (let attempt = 0; attempt < maxRetries; attempt++) {
812→        try {
813→          const url = `${gatewayUrl}/routing/v1/ipns/${ipnsName}`;
814→          const resp = await fetch(url, {
815→            headers: { 'Accept': 'application/vnd.ipfs.ipns-record' }
816→          });
817→
818→          if (resp.ok) {
819→            // The delegated routing API can return the IPNS record in different formats
820→            // Try JSON first (application/json), then raw record
821→            const contentType = resp.headers.get('Content-Type') || '';
822→
823→            if (contentType.includes('application/json')) {
824→              const json = await resp.json();
825→              // Extract CID from the record value
826→              if (json.record && json.record.value) {
827→                return extractCidFromValue(json.record.value);
828→              }
829→              if (json.value) {
830→                return extractCidFromValue(json.value);
831→              }
832→            }
833→
834→            // For vnd.ipfs.ipns-record, the response is a binary IPNS record
835→            // We need to parse the CBOR/protobuf to extract the Value field
836→            const recordBytes = new Uint8Array(await resp.arrayBuffer());
837→            const cid = extractCidFromIpnsRecord(recordBytes);
838→            if (cid) return cid;
839→          }
840→        } catch (e) {
841→          if (attempt < maxRetries - 1) {
842→            await sleep(1000 * Math.pow(2, attempt));
843→            continue;
844→          }
845→        }
846→      }
847→
848→      // Fallback: ipfs.io name resolve API
849→      for (let attempt = 0; attempt < maxRetries; attempt++) {
850→        try {
851→          const url = `https://ipfs.io/api/v0/name/resolve?arg=${ipnsName}`;
852→          const resp = await fetch(url);
853→          if (resp.ok) {
854→            const json = await resp.json();
855→            if (json.Path) {
856→              return extractCidFromValue(json.Path);
857→            }
858→          }
859→        } catch (e) {
860→          if (attempt < maxRetries - 1) {
861→            await sleep(1000 * Math.pow(2, attempt));
862→            continue;
863→          }
864→        }
865→      }
866→
867→      throw new Error(`Failed to resolve IPNS name: ${truncate(ipnsName, 20)}`);
868→    }
869→
870→    function extractCidFromValue(value) {
871→      // Value is typically "/ipfs/bafy..." - extract the CID
872→      if (typeof value === 'string') {
873→        if (value.startsWith('/ipfs/')) return value.slice(6);
874→        return value;
875→      }
876→      // If it's bytes (from CBOR), decode as string
877→      if (value instanceof Uint8Array) {
878→        const str = new TextDecoder().decode(value);
879→        if (str.startsWith('/ipfs/')) return str.slice(6);
880→        return str;
881→      }
882→      throw new Error('Unexpected IPNS value format');
883→    }
884→
885→    function extractCidFromIpnsRecord(recordBytes) {
886→      // IPNS records are protobuf-encoded.
887→      // The Value field is field number 2 (wire type 2 = length-delimited).
888→      // We need to find field 2 in the protobuf.
889→      try {
890→        let offset = 0;
891→        while (offset < recordBytes.length) {
892→          const fieldByte = recordBytes[offset];
893→          const fieldNumber = fieldByte >> 3;
894→          const wireType = fieldByte & 0x07;
895→
896→          offset++;
897→
898→          if (wireType === 2) {
899→            // Length-delimited
900→            let length = 0;
901→            let shift = 0;
902→            while (offset < recordBytes.length) {
903→              const b = recordBytes[offset++];
904→              length |= (b & 0x7f) << shift;
905→              if ((b & 0x80) === 0) break;
906→              shift += 7;
907→            }
908→
909→            if (fieldNumber === 2) {
910→              // Value field - this is the IPFS path
911→              const valueBytes = recordBytes.slice(offset, offset + length);
912→              const value = new TextDecoder().decode(valueBytes);
913→              return extractCidFromValue(value);
914→            }
915→
916→            offset += length;
917→          } else if (wireType === 0) {
918→            // Varint - skip
919→            while (offset < recordBytes.length && (recordBytes[offset] & 0x80) !== 0) offset++;
920→            offset++;
921→          } else {
922→            // Unknown wire type, bail
923→            break;
924→          }
925→        }
926→      } catch (e) {
927→        // Failed to parse protobuf
928→      }
929→      return null;
930→    }
