230→/// Encrypt root folder metadata as vault blob v2.
231→///
232→/// Wraps rootFolderKey in the blob header for zero-knowledge server operation.
233→/// Only used for root folder publishes -- subfolders use `encrypt_metadata_to_json`.
234→#[cfg(any(feature = "fuse", feature = "winfsp"))]
235→fn encrypt_root_metadata_to_v2_blob(
236→    metadata: &crate::crypto::folder::FolderMetadata,
237→    folder_key: &[u8],
238→    public_key: &[u8],
239→) -> Result<Vec<u8>, String> {
240→    // 1. Encrypt metadata to JSON bytes (existing logic)
241→    let json_bytes = encrypt_metadata_to_json(metadata, folder_key)?;
242→
243→    // 2. ECIES-wrap rootFolderKey with user's public key
244→    let encrypted_key = crate::crypto::ecies::wrap_key(folder_key, public_key)
245→        .map_err(|e| format!("Failed to wrap rootFolderKey for v2 blob: {}", e))?;
246→
247→    // 3. Produce v2 blob envelope
248→    crate::crypto::vault_blob::serialize_vault_blob_v2(&encrypted_key, &json_bytes)
249→}
