  1→//! Vault blob v2 format: binary envelope for root folder IPFS blobs.
  2→//!
  3→//! Format: 0x02 | uint16_BE(key_len) | ECIES_encrypted_key | AES_GCM_metadata_json
  4→//!
  5→//! v1 blobs are plain JSON: {"iv":"...","data":"..."}
  6→//! v2 blobs prepend the ECIES-wrapped rootFolderKey before the metadata JSON.
  7→
  8→/// Version byte for v2 format.
  9→pub const BLOB_V2_VERSION: u8 = 0x02;
 10→
 11→/// Detect whether a vault blob is v1 (JSON) or v2 (binary envelope).
 12→///
 13→/// v1 blobs start with 0x7B ('{' -- JSON). v2 blobs start with 0x02.
 14→pub fn detect_blob_version(blob: &[u8]) -> u8 {
 15→    if !blob.is_empty() && blob[0] == BLOB_V2_VERSION {
 16→        2
 17→    } else {
 18→        1
 19→    }
 20→}
 21→
 22→/// Serialize a vault blob v2.
 23→///
 24→/// Produces: `0x02 | uint16_BE(key_len) | encrypted_root_folder_key | encrypted_metadata_json`
 25→pub fn serialize_vault_blob_v2(
 26→    encrypted_root_folder_key: &[u8],
 27→    encrypted_metadata_json: &[u8],
 28→) -> Result<Vec<u8>, String> {
 29→    if encrypted_root_folder_key.len() > u16::MAX as usize {
 30→        return Err(format!(
 31→            "Encrypted key too long for v2 blob ({} bytes, max {})",
 32→            encrypted_root_folder_key.len(),
 33→            u16::MAX
 34→        ));
 35→    }
 36→    let key_len = encrypted_root_folder_key.len() as u16;
 37→    let mut result =
 38→        Vec::with_capacity(3 + encrypted_root_folder_key.len() + encrypted_metadata_json.len());
 39→    result.push(BLOB_V2_VERSION);
 40→    result.push((key_len >> 8) as u8);
 41→    result.push((key_len & 0xff) as u8);
 42→    result.extend_from_slice(encrypted_root_folder_key);
 43→    result.extend_from_slice(encrypted_metadata_json);
 44→    Ok(result)
 45→}
 46→
 47→/// Deserialize a vault blob v2 into (encrypted_key, encrypted_metadata_json).
 48→///
 49→/// Returns borrowed slices into the original blob for zero-copy parsing.
 50→pub fn deserialize_vault_blob_v2(blob: &[u8]) -> Result<(&[u8], &[u8]), String> {
 51→    if blob.len() < 3 {
 52→        return Err(format!(
 53→            "Vault blob too short for v2 header (need at least 3 bytes, have {})",
 54→            blob.len()
 55→        ));
 56→    }
 57→    if blob[0] != BLOB_V2_VERSION {
 58→        return Err("Not a v2 vault blob".into());
 59→    }
 60→    let key_len = ((blob[1] as usize) << 8) | (blob[2] as usize);
 61→    if blob.len() < 3 + key_len {
 62→        return Err(format!(
 63→            "Vault blob too short for key (expected {} bytes, have {})",
 64→            key_len,
 65→            blob.len() - 3
 66→        ));
 67→    }
 68→    Ok((&blob[3..3 + key_len], &blob[3 + key_len..]))
 69→}
