354→      } catch (error) {
355→        console.error('[Auth] Bin initialization failed (non-blocking):', error);
356→      }
357→    })();
358→
359→    // Non-blocking: fetch retention config from API
360→    void (async () => {
361→      try {
362→        const config = await vaultControllerGetConfig();
363→        if (config.recycleBinRetentionDays != null) {
364→          useBinStore.getState().setRetentionDays(config.recycleBinRetentionDays);
365→        }
366→      } catch (error) {
367→        console.error('[Auth] Failed to fetch vault config (non-blocking):', error);
368→      }
369→    })();
370→  }, [getVaultKeypair, setVaultKeypair, setVaultKeys]);
