449→  /**
450→   * Login with Google OAuth token.
451→   * Flow: Google idToken -> CipherBox backend -> CipherBox JWT ->
452→   * Core Kit loginWithJWT -> backend /auth/login (corekit type)
453→   */
454→  const loginWithGoogle = useCallback(
455→    async (googleIdToken: string): Promise<void> => {
456→      if (isLoggingIn) return;
457→      setIsLoggingIn(true);
458→      try {
459→        // 1. Core Kit login via CipherBox identity provider
460→        const {
461→          cipherboxJwt,
462→          email,
463→          userId,
464→          status: coreKitStatus,
465→        } = await coreKitLoginGoogle(googleIdToken);
466→
467→        if (coreKitStatus === 'required_share') {
468→          // MFA enabled but device factor missing.
469→          // Store pending auth info for later completion after factor input.
470→          setPendingAuth(cipherboxJwt, 'google');
471→
472→          // Obtain temporary backend access token so the new device can
473→          // call bulletin board API endpoints (device-approval/*).
474→          // Uses placeholder publicKey since Core Kit is in REQUIRED_SHARE
475→          // state and we can't export the TSS key yet.
476→          const tempLoginResponse = await authApi.login({
477→            idToken: cipherboxJwt,
478→            publicKey: `pending-core-kit-${userId}`,
479→            loginType: 'corekit',
480→          });
481→          setAccessToken(tempLoginResponse.accessToken);
482→
483→          if (email) {
484→            setUserEmail(email);
485→          }
486→
487→          // Do NOT call completeBackendAuth() or navigate('/files')
488→          // The component tree will see isRequiredShare === true and
489→          // render recovery/approval UI.
490→          return;
491→        }
492→
493→        // Normal path: Core Kit logged in, proceed as before
494→        // 2. Complete backend auth + vault init
495→        await completeBackendAuth('google', cipherboxJwt);
496→
497→        // 3. Store email for UI display (returned from identity endpoint)
498→        if (email) {
499→          setUserEmail(email);
500→        }
501→
502→        // Navigation handled by Login.tsx redirect effect (isAuthenticated → /files)
503→      } catch (error) {
504→        console.error('[useAuth] Google login failed:', error);
505→        throw error;
506→      } finally {
507→        setIsLoggingIn(false);
508→      }
509→    },
510→    [isLoggingIn, coreKitLoginGoogle, completeBackendAuth, setAccessToken, setUserEmail]
511→  );
512→
513→  /**
514→   * Login with Email OTP.
515→   * Flow: email+otp -> CipherBox backend -> CipherBox JWT ->
516→   * Core Kit loginWithJWT -> backend /auth/login (corekit type)
517→   */
518→  const loginWithEmail = useCallback(
519→    async (email: string, otp: string): Promise<void> => {
520→      if (isLoggingIn) return;
521→      setIsLoggingIn(true);
