525→
526→        if (coreKitStatus === 'required_share') {
527→          setPendingAuth(cipherboxJwt, 'email');
528→
529→          const tempLoginResponse = await authApi.login({
530→            idToken: cipherboxJwt,
531→            publicKey: `pending-core-kit-${userId}`,
532→            loginType: 'corekit',
533→          });
534→          setAccessToken(tempLoginResponse.accessToken);
535→          setUserEmail(email);
536→          return;
537→        }
538→
539→        // Normal path
540→        await completeBackendAuth('email', cipherboxJwt);
541→        setUserEmail(email);
542→        // Navigation handled by Login.tsx redirect effect (isAuthenticated → /files)
543→      } catch (error) {
544→        console.error('[useAuth] Email login failed:', error);
545→        throw error;
546→      } finally {
547→        setIsLoggingIn(false);
548→      }
549→    },
550→    [isLoggingIn, coreKitLoginEmail, completeBackendAuth, setAccessToken, setUserEmail]
551→  );
552→
553→  /**
554→   * Login with Wallet (SIWE).
555→   * Flow: Wallet connects + signs SIWE message -> backend verifies ->
556→   * CipherBox JWT -> Core Kit loginWithJWT -> backend /auth/login (corekit type)
557→   */
558→  const loginWithWallet = useCallback(
559→    async (cipherboxJwt: string, userId: string): Promise<void> => {
560→      if (isLoggingIn) return;
561→      setIsLoggingIn(true);
562→      try {
563→        // 1. Core Kit login via CipherBox identity provider
564→        const { status: coreKitStatus } = await coreKitLoginWallet(cipherboxJwt, userId);
565→
566→        if (coreKitStatus === 'required_share') {
567→          setPendingAuth(cipherboxJwt, 'wallet');
568→
569→          const tempLoginResponse = await authApi.login({
570→            idToken: cipherboxJwt,
571→            publicKey: `pending-core-kit-${userId}`,
572→            loginType: 'corekit',
573→          });
574→          setAccessToken(tempLoginResponse.accessToken);
575→          return;
576→        }
577→
578→        // Normal path
579→        await completeBackendAuth('wallet', cipherboxJwt);
580→        // Navigation is handled by Login.tsx's redirect effect (isAuthenticated → /files).
581→        // completeBackendAuth sets the access token early, but initializeOrLoadVault()
582→        // inside it may still be pending. An explicit navigate here would fire AFTER
583→        // vault init completes — by which point the user may have navigated away from
584→        // the login page, causing a disruptive late redirect.
585→      } catch (error) {
586→        console.error('[useAuth] Wallet login failed:', error);
587→        throw error;
588→      } finally {
589→        setIsLoggingIn(false);
590→      }
591→    },
592→    [isLoggingIn, coreKitLoginWallet, completeBackendAuth, setAccessToken]
593→  );
594→
595→  // Complete logout: Backend -> Core Kit -> Clear state
596→  const logout = useCallback(async () => {
597→    if (isLoggingOut) return;
598→
599→    setIsLoggingOut(true);
600→    try {
601→      // 1. Call backend logout (clears cookie)
602→      if (accessToken) {
603→        try {
604→          await authApi.logout();
605→        } catch {
606→          // Ignore errors -- we'll clear state anyway
607→        }
608→      }
609→
610→      // 2. Logout Core Kit (clears session from localStorage)
611→      await coreKitLogout();
612→
613→      // 3. Clear all user-scoped stores (centralized helper)
614→      clearAllUserStores();
615→
616→      // 4. Navigate to login
617→      navigate('/');
618→    } catch (error) {
619→      console.error('[useAuth] Logout failed:', error);
620→      // Still clear state even if backend fails
621→      clearAllUserStores();
622→      navigate('/');
623→    } finally {
624→      setIsLoggingOut(false);
625→    }
626→  }, [accessToken, coreKitLogout, navigate, isLoggingOut]);
627→
628→  // Keep function refs up-to-date for use in session restoration effect.
629→  // Using refs prevents the effect from re-firing when function identities change.
630→  initializeOrLoadVaultRef.current = initializeOrLoadVault;
631→  coreKitLogoutRef.current = coreKitLogout;
632→
633→  // Session restoration: if Core Kit restores a session from localStorage
634→  // on init, we have LOGGED_IN status without going through login flow.
635→  // Complete backend auth + vault loading.
636→  useEffect(() => {
637→    const restoreSession = async () => {
638→      // Only restore if Core Kit has a session but we don't have
639→      // a backend access token yet
640→      if (coreKitLoggedIn && !isAuthenticated && !isLoggingIn && !restoringRef.current) {
641→        restoringRef.current = true;
642→        setIsLoggingIn(true);
643→        try {
644→          // Try to refresh using the HTTP-only cookie first
645→          const response = await authApi.refresh();
646→          setAccessToken(response.accessToken);
647→
648→          // Restore email from backend if available
649→          if (response.email) {
650→            setUserEmail(response.email);
651→          }
