 32→import { initializeOrSyncRegistry } from '../services/device-registry.service';
 33→import { initializeBin } from '../services/bin.service';
 34→import { useBinStore } from '../stores/bin.store';
 35→import { vaultControllerGetConfig, vaultControllerMigrateVault } from '@cipherbox/api-client';
 36→import { createAndPublishIpnsRecord, resolveIpnsRecord } from '../services/ipns.service';
 37→import { addToIpfs, fetchFromIpfs } from '../lib/api/ipfs';
 38→
 39→export function useAuth() {
 40→  const navigate = useNavigate();
 41→  const {
 42→    isLoggedIn: coreKitLoggedIn,
 43→    isInitialized: coreKitInitialized,
 44→    isRequiredShare,
 45→    loginWithGoogle: coreKitLoginGoogle,
 46→    loginWithEmailOtp: coreKitLoginEmail,
 47→    loginWithWallet: coreKitLoginWallet,
 48→    getVaultKeypair,
 49→    getPublicKeyHex,
 50→    logout: coreKitLogout,
 51→  } = useCoreKitAuth();
 52→  const { syncStatus } = useCoreKit();
 53→  const {
 54→    accessToken,
 55→    isAuthenticated,
 56→    lastAuthMethod,
 57→    userEmail,
 58→    setAccessToken,
 59→    setAuthenticated,
 60→    setLastAuthMethod,
 61→    setUserEmail,
 62→    setVaultKeypair,
 63→  } = useAuthStore();
 64→
 65→  const [isLoggingIn, setIsLoggingIn] = useState(false);
 66→  const [isLoggingOut, setIsLoggingOut] = useState(false);
 67→  const restoringRef = useRef(false);
 68→
 69→  // Stable refs for functions used in the session restoration effect.
 70→  // This prevents the effect from re-firing when function references change.
 71→  const initializeOrLoadVaultRef = useRef<(() => Promise<void>) | null>(null);
 72→  const coreKitLogoutRef = useRef<(() => Promise<void>) | null>(null);
 73→
 74→  // Pending auth state for REQUIRED_SHARE flow.
 75→  // Stored in Zustand (not useState) so the state is shared across all
 76→  // useAuth() hook instances — Login.tsx sets it, useDeviceApproval reads it
 77→  // via its own useAuth() call.
 78→  const pendingAuthMethod = useAuthStore((s) => s.pendingAuthMethod);
 79→  const setPendingAuth = useAuthStore((s) => s.setPendingAuth);
 80→
 81→  const isLoading = !coreKitInitialized || isLoggingIn || isLoggingOut;
 82→
 83→  // Get vault store actions
 84→  const setVaultKeys = useVaultStore((state) => state.setVaultKeys);
 85→
 86→  /**
 87→   * Initialize vault for new users or load existing vault keys.
 88→   * Called after successful backend authentication.
 89→   * Uses Core Kit's getVaultKeypair() instead of PnP provider.
 90→   */
 91→  const initializeOrLoadVault = useCallback(async (): Promise<void> => {
 92→    // Get user's secp256k1 keypair from Core Kit TSS export
 93→    const userKeypair = await getVaultKeypair();
 94→
 95→    if (!userKeypair) {
 96→      throw new Error('Failed to get vault keypair from Core Kit');
 97→    }
 98→
 99→    // Store keypair in auth store for crypto operations
100→    setVaultKeypair(userKeypair);
101→
102→    try {
103→      // Try to fetch existing vault
104→      const existingVault = await vaultApi.getVault();
105→
106→      // Store TEE keys if available
107→      if (existingVault.teeKeys) {
108→        useAuthStore.getState().setTeeKeys(existingVault.teeKeys);
109→      }
110→
111→      if (existingVault.migratedAt) {
112→        // PATH A: Migrated user -- read rootFolderKey from IPFS v2 blob
113→        // Derive IPNS keypair once (used for both resolution and vault keys)
114→        const ipnsKeypair = await deriveVaultIpnsKeypair(userKeypair.privateKey);
115→        let rootFolderKey: Uint8Array;
116→        try {
117→          const ipnsName = await deriveIpnsName(ipnsKeypair.publicKey);
118→
119→          // Resolve IPNS to CID using the existing IPNS service (handles signature verification)
120→          const resolved = await resolveIpnsRecord(ipnsName);
121→          if (!resolved) throw new Error('IPNS name not found for migrated vault');
122→
123→          // Fetch blob bytes from IPFS using the existing IPFS adapter
124→          const blobBytes = await fetchFromIpfs(resolved.cid);
125→
126→          if (detectBlobVersion(blobBytes) === 2) {
127→            const { encryptedRootFolderKey: encKey } = deserializeVaultBlobV2(blobBytes);
128→            rootFolderKey = await unwrapKey(encKey, userKeypair.privateKey);
129→          } else {
130→            throw new Error('Migrated vault but IPNS blob is v1 format');
131→          }
132→        } catch (ipfsError) {
133→          // Silent DB fallback for migrated users (per CONTEXT decision)
134→          console.warn('[Auth] v2 blob read failed, falling back to DB:', ipfsError);
135→          if (existingVault.encryptedRootFolderKey) {
136→            rootFolderKey = await unwrapKey(
137→              hexToBytes(existingVault.encryptedRootFolderKey as unknown as string),
138→              userKeypair.privateKey
139→            );
140→          } else {
141→            // DB fields are null and IPFS failed -- cannot recover
142→            throw new Error('Migrated vault: IPFS read failed and no DB fallback available');
143→          }
144→        }
145→
146→        setVaultKeys({
147→          rootFolderKey,
148→          rootIpnsKeypair: ipnsKeypair,
149→          rootIpnsName: existingVault.rootIpnsName,
150→          vaultId: existingVault.id,
151→        });
152→      } else {
153→        // PATH B: Non-migrated existing user -- decrypt from DB + trigger migration
154→        const decryptedVault = await decryptVaultKeys(
155→          {
156→            encryptedRootFolderKey: hexToBytes(
157→              existingVault.encryptedRootFolderKey as unknown as string
158→            ),
159→            encryptedIpnsPrivateKey: hexToBytes(
160→              existingVault.encryptedRootIpnsPrivateKey as unknown as string
161→            ),
162→          },
163→          userKeypair.privateKey
164→        );
165→
166→        setVaultKeys({
167→          rootFolderKey: decryptedVault.rootFolderKey,
168→          rootIpnsKeypair: decryptedVault.rootIpnsKeypair,
169→          rootIpnsName: existingVault.rootIpnsName,
170→          vaultId: existingVault.id,
171→        });
172→
173→        // Non-blocking migration trigger: write v2 blob + call /vault/migrate
174→        void (async () => {
175→          try {
176→            // 1. ECIES-wrap rootFolderKey with user's publicKey
177→            const encryptedKey = await wrapKey(decryptedVault.rootFolderKey, userKeypair.publicKey);
178→
179→            // 2. Resolve current IPNS to get existing blob and sequence number
180→            const ipnsName = existingVault.rootIpnsName;
181→            const resolved = await resolveIpnsRecord(ipnsName);
182→            if (!resolved) throw new Error('IPNS name not found during migration');
183→            const currentSeqNo = resolved.sequenceNumber;
184→
185→            // 3. Fetch current blob (v1 JSON metadata)
186→            const existingMetadataJson = await fetchFromIpfs(resolved.cid);
187→
188→            // 4. Serialize as v2 blob
189→            const v2Blob = serializeVaultBlobV2(encryptedKey, existingMetadataJson);
190→
191→            // 5. Upload v2 blob to IPFS
192→            const uploadResult = await addToIpfs(new Blob([v2Blob as BlobPart]));
193→
194→            // 6. Publish IPNS record pointing to the new v2 blob CID.
195→            //    Uses createAndPublishIpnsRecord from ipns.service.ts which handles
196→            //    record creation, Ed25519 signing, marshaling, and API relay.
197→            //    Pass the current sequence number + 1 and expectedSequenceNumber
198→            //    for optimistic concurrency (prevents stale overwrites from
199→            //    concurrent publishes on another device).
200→            const ipnsKeypair = await deriveVaultIpnsKeypair(userKeypair.privateKey);
201→            const publishResult = await createAndPublishIpnsRecord({
202→              ipnsPrivateKey: ipnsKeypair.privateKey,
203→              ipnsName,
204→              metadataCid: uploadResult.cid,
205→              sequenceNumber: currentSeqNo + 1n,
206→              expectedSequenceNumber: currentSeqNo.toString(),
207→            });
208→
209→            if (!publishResult.success) {
210→              throw new Error('IPNS publish failed during vault migration');
211→            }
212→
213→            // 7. Call POST /vault/migrate to stamp migratedAt and NULL columns
214→            //    Only called AFTER confirmed v2 blob write + IPNS publish success
215→            //    (per CONTEXT decision: "do NOT stamp migratedAt until the v2 blob is confirmed written")
216→            await vaultControllerMigrateVault();
217→            console.log('[Auth] Vault successfully migrated to v2 blob format');
218→          } catch (migrationError) {
219→            // Migration failure is non-blocking. User can still use the app.
220→            // Migration will be retried on next login.
221→            console.warn(
222→              '[Auth] Vault v2 migration failed (will retry on next login):',
223→              migrationError
224→            );
225→          }
226→        })();
227→      }
228→    } catch (error) {
229→      const is404 = (error as { response?: { status?: number } })?.response?.status === 404;
230→
231→      if (is404) {
232→        // New user - initialize vault
233→        console.log(
234→          '[Auth] New user on Core Kit. If migrating from PnP, vault re-initialization may be needed.'
235→        );
236→        const newVault = await initializeVault(userKeypair.privateKey);
237→        const encryptedVault = await encryptVaultKeys(newVault, userKeypair.publicKey);
238→        const rootIpnsName = await deriveIpnsName(newVault.rootIpnsKeypair.publicKey);
239→
240→        const storedVault = await vaultApi.initVault({
241→          ownerPublicKey: bytesToHex(userKeypair.publicKey),
242→          encryptedRootFolderKey: bytesToHex(encryptedVault.encryptedRootFolderKey),
243→          // encryptedRootIpnsPrivateKey omitted -- HKDF derivation is canonical (VAULT-04)
244→          rootIpnsName,
245→        });
246→
247→        if (storedVault.teeKeys) {
248→          useAuthStore.getState().setTeeKeys(storedVault.teeKeys);
249→        }
250→
251→        setVaultKeys({
252→          rootFolderKey: newVault.rootFolderKey,
253→          rootIpnsKeypair: newVault.rootIpnsKeypair,
254→          rootIpnsName,
255→          vaultId: storedVault.id,
256→          isNewVault: true,
257→        });
258→      } else {
259→        console.error('[useAuth] Failed to load vault:', error);
260→        throw error;
261→      }
262→    }
263→
264→    // Initialize SDK client with decrypted vault keys
265→    const vaultState = useVaultStore.getState();
266→    const authState = useAuthStore.getState();
267→    if (vaultState.rootFolderKey && vaultState.rootIpnsKeypair && vaultState.rootIpnsName) {
268→      const apiUrl = import.meta.env.VITE_API_URL || window.location.origin + '/api';
269→      const getAccessToken = async () => {
270→        const state = useAuthStore.getState();
271→        return state.accessToken || '';
272→      };
273→
274→      // @cipherbox/api-client is configured in lib/api-config.ts at module load time.
275→
276→      const sdkClient = initSdkClient({
277→        apiUrl,
278→        getAccessToken,
279→        vaultKeypair: {
280→          publicKey: userKeypair.publicKey,
281→          privateKey: userKeypair.privateKey,
282→        },
283→        rootIpnsName: vaultState.rootIpnsName,
284→        rootFolderKey: vaultState.rootFolderKey,
285→        teeKeys: authState.teeKeys ?? undefined,
286→        shareCallbacks: {
287→          getCoveringShares: async (folderIpnsName: string) => {
288→            const { findCoveringShares } = await import('../services/share.service');
289→            const folders = useFolderStore.getState().folders;
290→            // Find the folder ID from IPNS name for ancestor traversal
291→            const folderId =
292→              Object.keys(folders).find((id) => folders[id].ipnsName === folderIpnsName) ?? null;
293→            return findCoveringShares(folderIpnsName, folders, folderId);
294→          },
295→          addShareKeys: async (shareId, keys) => {
296→            const { addShareKeys } = await import('../services/share.service');
297→            await addShareKeys(shareId, keys);
298→          },
299→        },
300→      });
301→
302→      // Subscribe folder store to SDK events
303→      useFolderStore.getState().subscribeToSdk(sdkClient);
304→
305→      // Subscribe bin store to SDK events
306→      useBinStore.getState().subscribeToSdk(sdkClient);
307→    }
308→
309→    // Non-blocking device registry initialization (fire-and-forget)
310→    // Placed after vault load so registry failures never block login
311→    void (async () => {
312→      try {
313→        const deviceKeypair = await getOrCreateDeviceIdentity({
314→          mode: 'persisted',
315→          vaultPrivateKey: userKeypair.privateKey,
316→        });
317→        const deviceInfo = detectDeviceInfo();
318→        const result = await initializeOrSyncRegistry({
319→          userPrivateKey: userKeypair.privateKey,
320→          userPublicKey: userKeypair.publicKey,
321→          deviceKeypair,
322→          deviceInfo: { ...deviceInfo, ipHash: '' },
323→        });
324→        if (result) {
325→          useDeviceRegistryStore
326→            .getState()
327→            .setRegistry(result.registry, result.ipnsName, deviceKeypair.deviceId);
328→        }
329→      } catch (error) {
330→        console.error('[Auth] Device registry init failed (non-blocking):', error);
331→      }
332→    })();
333→
334→    // Non-blocking bin initialization (fire-and-forget)
335→    // After old service creates/loads bin, also load into SDK for deleteToBin support
336→    void (async () => {
337→      try {
338→        await initializeBin({
339→          userPrivateKey: userKeypair.privateKey,
340→          userPublicKey: userKeypair.publicKey,
341→        });
342→        // Now load bin into SDK (old service ensures bin IPNS record exists)
343→        const { getSdkClient, hasSdkClient } = await import('../lib/sdk-provider');
344→        if (hasSdkClient()) {
345→          await getSdkClient().loadBin();
346→        }
347→      } catch (error) {
348→        console.error('[Auth] Bin initialization failed (non-blocking):', error);
349→      }
350→    })();
351→
352→    // Non-blocking: fetch retention config from API
353→    void (async () => {
354→      try {
355→        const config = await vaultControllerGetConfig();
356→        if (config.recycleBinRetentionDays != null) {
357→          useBinStore.getState().setRetentionDays(config.recycleBinRetentionDays);
358→        }
359→      } catch (error) {
360→        console.error('[Auth] Failed to fetch vault config (non-blocking):', error);
361→      }
362→    })();
363→  }, [getVaultKeypair, setVaultKeypair, setVaultKeys]);
364→
365→  /**
366→   * Complete backend authentication after Core Kit login.
367→   * Sends the CipherBox-issued JWT (which we used for Core Kit loginWithJWT)
368→   * to the backend with loginType 'corekit'. The backend verifies it against
369→   * its own JWKS since CipherBox is the identity provider.
370→   */
371→  const completeBackendAuth = useCallback(
372→    async (authMethod: string, cipherboxJwt: string): Promise<void> => {
373→      // 1. Get real publicKey from Core Kit TSS export
374→      const publicKey = await getPublicKeyHex();
375→      if (!publicKey) {
376→        throw new Error('Failed to get publicKey from Core Kit');
377→      }
378→
379→      // publicKey available for debugging via DevTools if needed
380→
381→      // 2. Authenticate with CipherBox backend
382→      // Backend verifies our CipherBox JWT and resolves placeholder publicKey
383→      const response = await authApi.login({
384→        idToken: cipherboxJwt,
385→        publicKey,
386→        loginType: 'corekit',
387→      });
388→
389→      // 3. Store access token (refresh token in HTTP-only cookie)
390→      // Note: this does NOT set isAuthenticated — we wait until vault + SDK
391→      // are fully initialized to prevent Login.tsx from redirecting to /files
392→      // before the SDK client is ready for file operations.
393→      setAccessToken(response.accessToken);
394→
395→      // 4. Remember auth method for UX
396→      setLastAuthMethod(authMethod);
397→
398→      // 5. Initialize or load vault + SDK client
399→      await initializeOrLoadVault();
400→
401→      // 6. Now that vault keys are loaded and SDK is initialized,
402→      // mark the user as authenticated. This triggers Login.tsx → /files redirect.
403→      setAuthenticated();
404→    },
405→    [getPublicKeyHex, setAccessToken, setAuthenticated, setLastAuthMethod, initializeOrLoadVault]
406→  );
407→
408→  /**
409→   * Complete the login flow after REQUIRED_SHARE is resolved.
410→   * Called after inputFactorKey() succeeds (from recovery phrase or cross-device approval).
411→   * Uses the stored pendingCipherboxJwt to call completeBackendAuth with the REAL publicKey
412→   * (since Core Kit is now LOGGED_IN), then navigates to /files.
413→   */
414→  const completeRequiredShare = useCallback(async (): Promise<void> => {
415→    // Read directly from Zustand store to get fresh values — this callback
416→    // may be called from useDeviceApproval's useAuth() instance, so we
417→    // can't rely on closure-captured selector values.
418→    const { pendingCipherboxJwt: jwt, pendingAuthMethod: method } = useAuthStore.getState();
419→
420→    if (!jwt || !method) {
421→      throw new Error('No pending auth info for REQUIRED_SHARE completion');
422→    }
423→
424→    // Core Kit should now be LOGGED_IN after inputFactorKey()
425→    // Complete backend auth with the REAL publicKey (replaces the placeholder session)
426→    await completeBackendAuth(method, jwt);
427→
428→    // NOW sync Core Kit React state to LOGGED_IN.
429→    // We deliberately delayed this from inputFactorKey() to prevent the session
430→    // restoration effect from firing before backend auth completed.
431→    // At this point isAuthenticated is true (from completeBackendAuth -> setAuthenticated),
432→    // so the session restore guard (coreKitLoggedIn && !isAuthenticated) won't trigger.
433→    syncStatus();
434→
435→    // Clear pending state
436→    setPendingAuth(null, null);
437→
438→    // Navigate to files
439→    navigate('/files');
440→  }, [completeBackendAuth, syncStatus, setPendingAuth, navigate]);
441→
442→  /**
443→   * Login with Google OAuth token.
444→   * Flow: Google idToken -> CipherBox backend -> CipherBox JWT ->
445→   * Core Kit loginWithJWT -> backend /auth/login (corekit type)
446→   */
447→  const loginWithGoogle = useCallback(
448→    async (googleIdToken: string): Promise<void> => {
449→      if (isLoggingIn) return;
450→      setIsLoggingIn(true);
451→      try {
452→        // 1. Core Kit login via CipherBox identity provider
453→        const {
454→          cipherboxJwt,
455→          email,
456→          userId,
457→          status: coreKitStatus,
458→        } = await coreKitLoginGoogle(googleIdToken);
459→
460→        if (coreKitStatus === 'required_share') {
461→          // MFA enabled but device factor missing.
462→          // Store pending auth info for later completion after factor input.
463→          setPendingAuth(cipherboxJwt, 'google');
464→
465→          // Obtain temporary backend access token so the new device can
466→          // call bulletin board API endpoints (device-approval/*).
467→          // Uses placeholder publicKey since Core Kit is in REQUIRED_SHARE
468→          // state and we can't export the TSS key yet.
469→          const tempLoginResponse = await authApi.login({
470→            idToken: cipherboxJwt,
471→            publicKey: `pending-core-kit-${userId}`,
472→            loginType: 'corekit',
473→          });
474→          setAccessToken(tempLoginResponse.accessToken);
475→
476→          if (email) {
477→            setUserEmail(email);
478→          }
479→
480→          // Do NOT call completeBackendAuth() or navigate('/files')
481→          // The component tree will see isRequiredShare === true and
482→          // render recovery/approval UI.
483→          return;
484→        }
485→
486→        // Normal path: Core Kit logged in, proceed as before
487→        // 2. Complete backend auth + vault init
488→        await completeBackendAuth('google', cipherboxJwt);
489→
490→        // 3. Store email for UI display (returned from identity endpoint)
491→        if (email) {
492→          setUserEmail(email);
493→        }
494→
495→        // Navigation handled by Login.tsx redirect effect (isAuthenticated → /files)
496→      } catch (error) {
497→        console.error('[useAuth] Google login failed:', error);
498→        throw error;
499→      } finally {
500→        setIsLoggingIn(false);
501→      }
502→    },
503→    [isLoggingIn, coreKitLoginGoogle, completeBackendAuth, setAccessToken, setUserEmail]
504→  );
505→
506→  /**
507→   * Login with Email OTP.
508→   * Flow: email+otp -> CipherBox backend -> CipherBox JWT ->
509→   * Core Kit loginWithJWT -> backend /auth/login (corekit type)
510→   */
511→  const loginWithEmail = useCallback(
512→    async (email: string, otp: string): Promise<void> => {
513→      if (isLoggingIn) return;
514→      setIsLoggingIn(true);
515→      try {
516→        // 1. Core Kit login via CipherBox identity provider
517→        const { cipherboxJwt, userId, status: coreKitStatus } = await coreKitLoginEmail(email, otp);
518→
519→        if (coreKitStatus === 'required_share') {
520→          setPendingAuth(cipherboxJwt, 'email');
521→
522→          const tempLoginResponse = await authApi.login({
523→            idToken: cipherboxJwt,
524→            publicKey: `pending-core-kit-${userId}`,
525→            loginType: 'corekit',
526→          });
527→          setAccessToken(tempLoginResponse.accessToken);
528→          setUserEmail(email);
529→          return;
530→        }
531→
532→        // Normal path
533→        await completeBackendAuth('email', cipherboxJwt);
534→        setUserEmail(email);
535→        // Navigation handled by Login.tsx redirect effect (isAuthenticated → /files)
536→      } catch (error) {
537→        console.error('[useAuth] Email login failed:', error);
538→        throw error;
539→      } finally {
540→        setIsLoggingIn(false);
541→      }
542→    },
543→    [isLoggingIn, coreKitLoginEmail, completeBackendAuth, setAccessToken, setUserEmail]
544→  );
545→
546→  /**
547→   * Login with Wallet (SIWE).
548→   * Flow: Wallet connects + signs SIWE message -> backend verifies ->
549→   * CipherBox JWT -> Core Kit loginWithJWT -> backend /auth/login (corekit type)
550→   */
551→  const loginWithWallet = useCallback(
552→    async (cipherboxJwt: string, userId: string): Promise<void> => {
553→      if (isLoggingIn) return;
554→      setIsLoggingIn(true);
555→      try {
556→        // 1. Core Kit login via CipherBox identity provider
557→        const { status: coreKitStatus } = await coreKitLoginWallet(cipherboxJwt, userId);
558→
559→        if (coreKitStatus === 'required_share') {
560→          setPendingAuth(cipherboxJwt, 'wallet');
561→
562→          const tempLoginResponse = await authApi.login({
563→            idToken: cipherboxJwt,
564→            publicKey: `pending-core-kit-${userId}`,
565→            loginType: 'corekit',
566→          });
567→          setAccessToken(tempLoginResponse.accessToken);
568→          return;
569→        }
570→
571→        // Normal path
572→        await completeBackendAuth('wallet', cipherboxJwt);
573→        // Navigation is handled by Login.tsx's redirect effect (isAuthenticated → /files).
574→        // completeBackendAuth sets the access token early, but initializeOrLoadVault()
575→        // inside it may still be pending. An explicit navigate here would fire AFTER
576→        // vault init completes — by which point the user may have navigated away from
577→        // the login page, causing a disruptive late redirect.
578→      } catch (error) {
579→        console.error('[useAuth] Wallet login failed:', error);
580→        throw error;
581→      } finally {
582→        setIsLoggingIn(false);
583→      }
584→    },
585→    [isLoggingIn, coreKitLoginWallet, completeBackendAuth, setAccessToken]
586→  );
587→
588→  // Complete logout: Backend -> Core Kit -> Clear state
589→  const logout = useCallback(async () => {
590→    if (isLoggingOut) return;
591→
592→    setIsLoggingOut(true);
593→    try {
594→      // 1. Call backend logout (clears cookie)
595→      if (accessToken) {
596→        try {
597→          await authApi.logout();
598→        } catch {
599→          // Ignore errors -- we'll clear state anyway
600→        }
601→      }
602→
603→      // 2. Logout Core Kit (clears session from localStorage)
604→      await coreKitLogout();
605→
606→      // 3. Clear all user-scoped stores (centralized helper)
607→      clearAllUserStores();
608→
609→      // 4. Navigate to login
610→      navigate('/');
611→    } catch (error) {
612→      console.error('[useAuth] Logout failed:', error);
613→      // Still clear state even if backend fails
614→      clearAllUserStores();
615→      navigate('/');
616→    } finally {
617→      setIsLoggingOut(false);
618→    }
619→  }, [accessToken, coreKitLogout, navigate, isLoggingOut]);
620→
621→  // Keep function refs up-to-date for use in session restoration effect.
622→  // Using refs prevents the effect from re-firing when function identities change.
623→  initializeOrLoadVaultRef.current = initializeOrLoadVault;
624→  coreKitLogoutRef.current = coreKitLogout;
625→
626→  // Session restoration: if Core Kit restores a session from localStorage
627→  // on init, we have LOGGED_IN status without going through login flow.
628→  // Complete backend auth + vault loading.
629→  useEffect(() => {
630→    const restoreSession = async () => {
631→      // Only restore if Core Kit has a session but we don't have
632→      // a backend access token yet
633→      if (coreKitLoggedIn && !isAuthenticated && !isLoggingIn && !restoringRef.current) {
634→        restoringRef.current = true;
635→        setIsLoggingIn(true);
636→        try {
637→          // Try to refresh using the HTTP-only cookie first
638→          const response = await authApi.refresh();
639→          setAccessToken(response.accessToken);
640→
641→          // Restore email from backend if available
642→          if (response.email) {
643→            setUserEmail(response.email);
644→          }
645→
646→          // Load vault keys from Core Kit keypair + initialize SDK
647→          await initializeOrLoadVaultRef.current?.();
648→
649→          // Mark as authenticated only after vault + SDK are ready
650→          setAuthenticated();
651→        } catch {
652→          // No valid backend session -- user needs to re-login
653→          // Core Kit session exists but backend cookie expired
654→          // Clear Core Kit session to avoid inconsistent state
655→          try {
656→            await coreKitLogoutRef.current?.();
657→          } catch {
658→            // Ignore logout errors during cleanup
659→          }
660→        } finally {
661→          restoringRef.current = false;
662→          setIsLoggingIn(false);
663→        }
664→      }
665→    };
666→    restoreSession();
667→  }, [
668→    coreKitLoggedIn,
669→    isAuthenticated,
670→    isLoggingIn,
671→    setAccessToken,
672→    setAuthenticated,
673→    setUserEmail,
674→  ]);
675→
676→  return {
677→    isLoading,
678→    isAuthenticated,
679→    isRequiredShare,
680→    lastAuthMethod,
681→    userEmail,
682→    pendingAuthMethod,
683→    loginWithGoogle,
684→    loginWithEmail,
685→    loginWithWallet,
686→    completeRequiredShare,
687→    logout,
688→  };
689→}
