 1→/**
 2→ * @cipherbox/crypto - ECIES Key Wrapping (Encryption)
 3→ *
 4→ * Wraps symmetric keys using ECIES with secp256k1.
 5→ * Uses eciesjs library which handles ephemeral keys, ECDH, HKDF, and AES-GCM internally.
 6→ */
 7→
 8→import { encrypt } from 'eciesjs';
 9→import { ProjectivePoint } from '@noble/secp256k1';
10→import { CryptoError } from '../types';
11→import { SECP256K1_PUBLIC_KEY_SIZE } from '../constants';
12→
13→/**
14→ * Wrap a key using ECIES encryption.
15→ *
16→ * Encrypts a symmetric key (or any data) to a recipient's public key.
17→ * Only the holder of the corresponding private key can unwrap it.
18→ *
19→ * Each call produces different ciphertext due to ephemeral key generation.
20→ *
21→ * @param key - Data to wrap (typically a 32-byte file key)
22→ * @param recipientPublicKey - 65-byte uncompressed secp256k1 public key
23→ * @returns Wrapped key ciphertext
24→ * @throws CryptoError with generic message on any failure
25→ */
26→export async function wrapKey(
27→  key: Uint8Array,
28→  recipientPublicKey: Uint8Array
29→): Promise<Uint8Array> {
30→  // Validate public key size (uncompressed secp256k1)
31→  if (recipientPublicKey.length !== SECP256K1_PUBLIC_KEY_SIZE) {
32→    throw new CryptoError('Key wrapping failed', 'INVALID_PUBLIC_KEY_SIZE');
33→  }
34→
35→  // Validate uncompressed public key prefix (0x04)
36→  if (recipientPublicKey[0] !== 0x04) {
37→    throw new CryptoError('Key wrapping failed', 'INVALID_PUBLIC_KEY_FORMAT');
38→  }
39→
40→  // Validate that the public key is a valid point on secp256k1 curve
41→  try {
42→    ProjectivePoint.fromHex(recipientPublicKey);
43→  } catch {
44→    throw new CryptoError('Key wrapping failed', 'INVALID_PUBLIC_KEY_FORMAT');
45→  }
46→
47→  try {
48→    // eciesjs encrypt handles:
49→    // 1. Generate ephemeral keypair
50→    // 2. ECDH key agreement
51→    // 3. HKDF key derivation
52→    // 4. AES-GCM encryption
53→    // 5. Return: ephemeral_pubkey || ciphertext || tag
54→    const wrapped = encrypt(recipientPublicKey, key);
55→    return wrapped;
56→  } catch {
57→    // Generic error to prevent information leakage
58→    throw new CryptoError('Key wrapping failed', 'KEY_WRAPPING_FAILED');
59→  }
60→}
