    const v2Blob = serializeVaultBlobV2(encryptedKey, existingMetadataJson);
    console.log('[Auth] Migration step 4 complete, v2Blob size:', v2Blob.length);

    // 5. Upload v2 blob to IPFS
    console.log('[Auth] Migration step 5: addToIpfs');
